// GENERATED by `yuu-dev bundle` from bundle.manifest - do not edit by hand.
// Edit the individual static/*.js files (or the manifest order) and re-run
// `yuu-dev bundle`. tests/unit/test_bundle_drift.py guards this file.

//# sourceURL=split.js
// Feature-map - Split recording into segments (code: segment / segment_start_s).
//   API: routes/videos.py (split) · Tests: tests/ui/test_ui_split.py, tests/integration/test_segments.py
// ── shared live split-editor state ────────────────────────────────────────────
// Read cross-file: videos.js checks _splitPoints for the "has splits" badge,
// analyze.js reads the segment plan, index.html's zoom buttons read _splitZoom,
// and an inline onchange writes _splitNames[i]. Kept at top level, outside the
// IIFE below, so the global lexical binding stays live - an Object.assign export
// would snapshot the value and inline handlers / readers would go stale.
let _splitDurationS = 0;
let _splitPoints    = [];  // sorted list of seconds
let _splitNames     = [];  // auto-names, editable
let _splitIgnored   = new Set();  // indices of segments to skip
let _splitZoom      = 1;

// Suggestion-pin inputs/outputs. Not read by other production modules, but the
// _computeSuggestionPins tests seed _splitEnergyFlat and read _suggestionPins
// directly via page.evaluate (global lexical scope) - so they too stay outside
// the IIFE rather than becoming closure-private.
let _splitEnergyFlat = [];   // [{second, rms_db}, …] merged across tracks
let _suggestionPins  = [];    // [sec, …]

(function () {
// ── split editor ─────────────────────────────────────────────────────────────
let _splitVideoId   = null;

// Overlay data fetched once when the editor opens
let _splitSceneMs    = [];   // [ms, …] scene boundary timecodes
let _splitClipRanges = [];   // [{start_ms, end_ms}, …] existing clips

// Drag state
let _dragMarkerSec  = null;
let _dragActive     = false;

// Timeline zoom (main split editor only): 1 = fit whole recording, higher =
// wider bar inside a horizontal-scroll container. All overlay layers are
// %-positioned so they scale for free; only the waveform canvas needs a redraw.
// (_splitZoom itself is hoisted to top level above - an inline zoom-button
// handler in index.html reads it.)
const _SPLIT_ZOOM_MIN = 1;
const _SPLIT_ZOOM_MAX = 50;

const _SUGGESTION_MIN_GAP_S = 30;
const _SUGGESTION_COUNT     = 8;

// One instruction string for both editors (L6-3); the main editor appends its
// extra affordances. Scripts load at the end of <body>, so the elements exist.
const SPLIT_BAR_INSTRUCTIONS =
  'Click the bar to place a split point. Drag a marker to move it; hover over it and click its × to remove it.';
document.getElementById('pre-split-instructions').textContent = SPLIT_BAR_INSTRUCTIONS;
document.getElementById('split-instructions').textContent =
  `${SPLIT_BAR_INSTRUCTIONS} Click a marker to jump the preview there. Each segment can be analyzed independently after confirming.`;

// Ctrl/⌘+wheel over the timeline zooms; passive:false so preventDefault sticks.
document.getElementById('split-timeline-scroll')
  ?.addEventListener('wheel', _onSplitZoomWheel, { passive: false });

function isSplitEditorOpen() {
  return PanelNav.isOpen('split-editor');
}

async function openSplitEditor(videoId) {
  const video = AppState.videos.find(v => v.id === videoId);
  if (!video) return;

  _splitVideoId   = videoId;
  _splitDurationS = (video.duration_ms || 0) / 1000;
  _splitPoints    = [];
  _splitNames     = [];
  _splitIgnored   = new Set();
  _splitEnergyFlat = [];
  _splitSceneMs    = [];
  _splitClipRanges = [];
  _suggestionPins  = [];

  PanelNav.open({
    id: 'split-editor',
    title: `Split: ${video.filename}`,
    render: container => _mountSplitEditorPanel(container, videoId),
    isDirty: () => _splitPoints.length > 0,
    onClose: _teardownSplitEditor,
  });

  await _loadSplitEditorOverlays(videoId);
}

function _mountSplitEditorPanel(container, videoId) {
  const panel = document.getElementById('split-editor-panel');
  container.appendChild(panel);
  panel.style.display = 'flex';

  const video = AppState.videos.find(v => v.id === videoId);
  document.getElementById('split-preview-wrap').style.display = 'block';
  setupRecordingPreview(
    document.getElementById('split-preview-video'),
    document.getElementById('split-preview-badge'),
    videoId,
    { autoBuild: true, isCurrent: () => _splitVideoId === videoId, sourcePath: video?.source_path },
  );

  document.getElementById('split-waveform-notice').style.display = 'none';

  // A destructive re-analyze choice must not persist into the next session.
  document.querySelector('input[name="split-action"][value="partition"]').checked = true;

  _resetSplitZoom();
  _renderSplitEditor();
}

async function _loadSplitEditorOverlays(videoId) {
  // Fetch overlay data in parallel; render progressively
  const [energyRes, sceneRes, clipsRes] = await Promise.allSettled([
    fetch(`/api/videos/${videoId}/energy`).then(r => r.ok ? r.json() : null),
    fetch(`/api/videos/${videoId}/scene-boundaries`).then(r => r.ok ? r.json() : null),
    fetch(`/api/videos/${videoId}/clips`).then(r => r.ok ? r.json() : null),
  ]);

  let hasEnergy = false;
  if (energyRes.status === 'fulfilled' && energyRes.value?.tracks?.length) {
    const bySecond = new Map();
    for (const track of energyRes.value.tracks) {
      for (const s of track.samples) {
        const prev = bySecond.get(s.second);
        if (prev === undefined || s.rms_db > prev) bySecond.set(s.second, s.rms_db);
      }
    }
    if (bySecond.size > 0) {
      hasEnergy = true;
      _splitEnergyFlat = Array.from(bySecond.entries())
        .sort((a, b) => a[0] - b[0])
        .map(([second, rms_db]) => ({ second, rms_db }));
      _computeSuggestionPins();
      _drawWaveform();
    }
  }

  if (!hasEnergy) {
    document.getElementById('split-waveform-notice').style.display = 'flex';
  }

  if (sceneRes.status === 'fulfilled' && sceneRes.value?.boundaries_ms) {
    _splitSceneMs = sceneRes.value.boundaries_ms;
    _renderSceneLayer();
  }

  if (clipsRes.status === 'fulfilled' && clipsRes.value?.length) {
    _splitClipRanges = clipsRes.value.map(c => ({
      start_ms: c.start_ms,
      end_ms: c.end_ms,
    }));
    _renderClipsLayer();
  }

  _renderSuggestionLayer();
}

// Force-closes the panel (bypasses PanelNav's dirty gate) - used by callers
// that already ran their own confirm (e.g. switching recordings) and by the
// split editor's own post-confirm success paths.
function closeSplitEditor() {
  PanelNav.forceClose();
}

function _teardownSplitEditor() {
  const previewEl = document.getElementById('split-preview-video');
  previewEl.pause();
  previewEl.src = '';
  document.getElementById('split-preview-wrap').style.display = 'none';
  const badge = document.getElementById('split-preview-badge');
  if (badge) badge.style.display = 'none';
  const panel = document.getElementById('split-editor-panel');
  panel.style.display = 'none';
  // PanelNav removes its container (and everything still inside it) right
  // after onClose() runs - move the panel's static markup back out first so
  // it survives to be reparented into the next PanelNav container on reopen.
  document.getElementById('panelnav-root').insertAdjacentElement('afterend', panel);
  document.getElementById('split-waveform-notice').style.display = 'none';
  _splitVideoId   = null;
  _dragActive     = false;
  _dragMarkerSec  = null;
}

function _splitSeekTo(sec) {
  const v = document.getElementById('split-preview-video');
  if (v && v.src) {
    v.currentTime = sec;
    v.play().catch(() => {});
  }
}

// Preview proxy (720p, fast scrubbing) is handled by the shared
// setupRecordingPreview() in utils.js - see openSplitEditor.

async function _generateWaveform() {
  const btn = document.querySelector('#split-waveform-notice button');
  if (btn) { btn.disabled = true; btn.textContent = 'Generating…'; }
  const notice = document.getElementById('split-waveform-notice');

  streamSSE(
    `/api/videos/${_splitVideoId}/compute-waveform`,
    async () => {
      // Reload energy data and redraw
      const res = await fetch(`/api/videos/${_splitVideoId}/energy`).then(r => r.ok ? r.json() : null);
      if (res?.tracks?.length) {
        const bySecond = new Map();
        for (const track of res.tracks) {
          for (const s of track.samples) {
            const prev = bySecond.get(s.second);
            if (prev === undefined || s.rms_db > prev) bySecond.set(s.second, s.rms_db);
          }
        }
        if (bySecond.size > 0) {
          _splitEnergyFlat = Array.from(bySecond.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([second, rms_db]) => ({ second, rms_db }));
          _computeSuggestionPins();
          _drawWaveform();
          notice.style.display = 'none';
          return;
        }
      }
      if (btn) { btn.disabled = false; btn.textContent = 'Generate Waveform'; }
    },
    null,
    'Waveform',
    false,
  );
}

// ── suggestion pins ──────────────────────────────────────────────────────────

function _computeSuggestionPins() {
  if (!_splitEnergyFlat.length || !_splitDurationS) return;

  // Work with normalised linear energy (not dB) for valley detection
  const minDb = Math.min(..._splitEnergyFlat.map(s => s.rms_db));
  const maxDb = Math.max(..._splitEnergyFlat.map(s => s.rms_db));
  const range  = maxDb - minDb || 1;

  // Score each second: 1 = quietest, 0 = loudest
  const scored = _splitEnergyFlat.map(s => ({
    sec:   s.second,
    score: 1 - (s.rms_db - minDb) / range,
  }));

  // Greedy pick: take the highest-scoring second not within gap of a chosen pin
  const sorted = [...scored].sort((a, b) => b.score - a.score);
  const pins = [];
  for (const { sec } of sorted) {
    if (pins.length >= _SUGGESTION_COUNT) break;
    if (sec <= 0 || sec >= _splitDurationS) continue;
    if (pins.some(p => Math.abs(p - sec) < _SUGGESTION_MIN_GAP_S)) continue;
    pins.push(sec);
  }
  _suggestionPins = pins.sort((a, b) => a - b);
}

// ── timeline zoom ─────────────────────────────────────────────────────────────

function _fmtZoom(z) {
  return (z >= 9.95 ? Math.round(z) : Math.round(z * 10) / 10) + '×';
}

function _resetSplitZoom() {
  _splitZoom = 1;
  const bar    = document.getElementById('split-timeline-bar');
  const scroll = document.getElementById('split-timeline-scroll');
  const label  = document.getElementById('split-zoom-label');
  if (bar)    bar.style.width = '100%';
  if (scroll) scroll.scrollLeft = 0;
  if (label)  label.textContent = _fmtZoom(1);
  _updateSplitZoomButtons();
}

function _updateSplitZoomButtons() {
  const out = document.getElementById('split-zoom-out');
  const inb = document.getElementById('split-zoom-in');
  if (out) out.disabled = _splitZoom <= _SPLIT_ZOOM_MIN + 1e-6;
  if (inb) inb.disabled = _splitZoom >= _SPLIT_ZOOM_MAX - 1e-6;
}

// Set the zoom factor, keeping the timeline point under *anchorClientX* fixed on
// screen (falls back to the viewport centre for button clicks).
function _setSplitZoom(zoom, anchorClientX) {
  const bar    = document.getElementById('split-timeline-bar');
  const scroll = document.getElementById('split-timeline-scroll');
  const label  = document.getElementById('split-zoom-label');
  if (!bar || !scroll) return;

  const newZoom = Math.max(_SPLIT_ZOOM_MIN, Math.min(_SPLIT_ZOOM_MAX, zoom));
  const oldW    = bar.offsetWidth || scroll.clientWidth;
  const anchorX = anchorClientX != null
    ? anchorClientX - scroll.getBoundingClientRect().left
    : scroll.clientWidth / 2;
  const anchorFrac = oldW ? (scroll.scrollLeft + anchorX) / oldW : 0;

  _splitZoom = newZoom;
  bar.style.width = (newZoom * 100) + '%';
  if (label) label.textContent = _fmtZoom(newZoom);

  _drawWaveform();                       // redraw at the new pixel width
  scroll.scrollLeft = anchorFrac * bar.offsetWidth - anchorX;
  _updateSplitZoomButtons();
}

function _onSplitZoomWheel(e) {
  if (!(e.ctrlKey || e.metaKey)) return;  // plain wheel keeps scrolling/panning
  e.preventDefault();
  _setSplitZoom(_splitZoom * (e.deltaY < 0 ? 1.25 : 1 / 1.25), e.clientX);
}

// ── canvas waveform ──────────────────────────────────────────────────────────

function _drawWaveform() {
  const canvas = document.getElementById('split-waveform-canvas');
  if (!canvas || !_splitEnergyFlat.length || !_splitDurationS) return;

  // Use layout size, not CSS pixel size. Clamp the bitmap width so a deep zoom
  // on a multi-hour recording can't exceed the browser's max canvas dimension;
  // CSS stretches the (soft, semi-transparent) waveform over any excess.
  const W = Math.min(canvas.offsetWidth || 800, 16000);
  const H = canvas.offsetHeight || 60;
  canvas.width  = W;
  canvas.height = H;

  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, W, H);

  const minDb = Math.min(..._splitEnergyFlat.map(s => s.rms_db));
  const maxDb = Math.max(..._splitEnergyFlat.map(s => s.rms_db));
  const range  = maxDb - minDb || 1;

  // Downsample to one bar per CSS pixel bucket
  const buckets = new Float32Array(W);
  const counts  = new Uint16Array(W);
  for (const { second, rms_db } of _splitEnergyFlat) {
    const x = Math.floor((second / _splitDurationS) * W);
    if (x >= 0 && x < W) {
      buckets[x] += rms_db;
      counts[x]++;
    }
  }

  // Filled path from bottom, centred vertically
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let x = 0; x < W; x++) {
    const avg = counts[x] ? buckets[x] / counts[x] : minDb;
    const norm = (avg - minDb) / range;            // 0..1
    const barH = Math.max(2, norm * H * 0.85);
    ctx.lineTo(x, H - barH);
  }
  ctx.lineTo(W, H);
  ctx.closePath();

  // Use CSS variable for accent with low opacity
  const style = getComputedStyle(document.documentElement);
  const accent = style.getPropertyValue('--accent').trim() || '#6c8ebf';
  ctx.fillStyle = accent + '55';   // ~33 % opacity
  ctx.fill();
}

// ── scene boundary layer ─────────────────────────────────────────────────────

function _renderSceneLayer() {
  const el = document.getElementById('split-scene-layer');
  if (!el || !_splitDurationS) return;

  el.innerHTML = _splitSceneMs.map(ms => {
    const pct = (ms / 1000 / _splitDurationS * 100).toFixed(3);
    return `<div style="position:absolute;left:${pct}%;top:0;bottom:0;width:1px;background:color-mix(in srgb, var(--text) 30%, transparent)" title="Scene cut at ${_fmtSplitTime(ms / 1000)}"></div>`;
  }).join('');
}

// ── suggestion pin layer ─────────────────────────────────────────────────────

function _renderSuggestionLayer() {
  const el = document.getElementById('split-suggestion-layer');
  if (!el || !_splitDurationS) return;

  el.innerHTML = _suggestionPins.map(sec => {
    // Hide if already a real marker
    if (_splitPoints.some(p => Math.abs(p - sec) < 1)) return '';
    const pct = (sec / _splitDurationS * 100).toFixed(3);
    return `<div data-pin="${sec}" class="split-suggestion-pin"
                 style="position:absolute;left:${pct}%;top:0;bottom:0;width:14px;transform:translateX(-50%);cursor:pointer;pointer-events:auto;display:flex;justify-content:center"
                 title="Quiet valley at ${_fmtSplitTime(sec)} - click to place a split point here"
                 onclick="event.stopPropagation();_promoteSuggestionPin(${sec})">
               <div style="width:0;border-left:1.5px dashed color-mix(in srgb, var(--text) 40%, transparent)"></div>
             </div>`;
  }).join('');
}

function _promoteSuggestionPin(sec) {
  if (_splitPoints.some(p => Math.abs(p - sec) < 0.5)) return;
  _splitPoints.push(sec);
  _splitPoints.sort((a, b) => a - b);
  _rebuildSplitNames();
  _renderSplitEditor();
}

// ── existing clips dot layer ─────────────────────────────────────────────────

function _renderClipsLayer() {
  const el = document.getElementById('split-clips-layer');
  if (!el || !_splitDurationS) return;

  el.innerHTML = _splitClipRanges.map(({ start_ms, end_ms }) => {
    const leftPct  = (start_ms / 1000 / _splitDurationS * 100).toFixed(3);
    const widthPct = ((end_ms - start_ms) / 1000 / _splitDurationS * 100).toFixed(3);
    return `<div style="position:absolute;left:${leftPct}%;width:${widthPct}%;top:50%;transform:translateY(-50%);height:4px;background:color-mix(in srgb, var(--text) 22%, transparent);border-radius:2px" title="Existing clip ${_fmtSplitTime(start_ms/1000)}–${_fmtSplitTime(end_ms/1000)}"></div>`;
  }).join('');
}

// ── drag-to-reposition markers ────────────────────────────────────────────────

function _splitMarkerPointerDown(e, sec) {
  e.stopPropagation();
  e.preventDefault();
  _dragMarkerSec = sec;
  _dragActive    = true;
  let moved      = false;

  const bar = document.getElementById('split-timeline-bar');

  function onMove(ev) {
    if (!_dragActive) return;
    moved = true;
    const rect = bar.getBoundingClientRect();
    const frac = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width));
    const newSec = Math.round(frac * _splitDurationS * 10) / 10;
    if (newSec <= 0 || newSec >= _splitDurationS) return;

    const idx = _splitPoints.indexOf(_dragMarkerSec);
    if (idx !== -1) {
      _splitPoints[idx] = newSec;
      _dragMarkerSec = newSec;
      _splitPoints.sort((a, b) => a - b);
      _renderSplitEditor();
    }
  }

  function onUp() {
    _dragActive    = false;
    if (!moved) _splitSeekTo(sec);
    _dragMarkerSec = null;
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup',   onUp);
    _rebuildSplitNames();
    _renderSplitEditor();
  }

  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup',   onUp);
}

// ── main click handler ───────────────────────────────────────────────────────

function splitTimelineClick(e) {
  if (!_splitDurationS || _dragActive) return;
  const bar  = document.getElementById('split-timeline-bar');
  const rect = bar.getBoundingClientRect();
  const frac = (e.clientX - rect.left) / rect.width;
  const sec  = Math.round(frac * _splitDurationS * 10) / 10;

  if (sec <= 0 || sec >= _splitDurationS) return;

  // Too close to an existing marker - ignore rather than stack a near-duplicate
  // (removal is via the marker's × button).
  const threshold = _splitDurationS * 0.005;
  if (_splitPoints.some(p => Math.abs(p - sec) <= threshold)) return;

  _splitPoints.push(sec);
  _splitPoints.sort((a, b) => a - b);
  _rebuildSplitNames();
  _renderSplitEditor();
}

function _removeSplitPoint(sec, isPreSplit) {
  const idx = _splitPoints.indexOf(sec);
  if (idx === -1) return;
  _splitPoints.splice(idx, 1);
  if (isPreSplit) {
    _rebuildPreSplitNames();
    _renderPreSplitEditor();
  } else {
    _rebuildSplitNames();
    _renderSplitEditor();
  }
}

// ── render ───────────────────────────────────────────────────────────────────

function _rebuildSplitNames() {
  if (!_splitVideoId) return;
  const video = AppState.videos.find(v => v.id === _splitVideoId);
  const stem  = video ? video.filename.replace(/\.[^.]+$/, '') : 'Recording';
  const count = _splitPoints.length + 1;
  _splitNames = Array.from({length: count}, (_, i) => `${stem} - Part ${i + 1}`);
}

function _renderSplitEditor() {
  _renderSplitTimeline();
  _updateSplitConfirmState();  // also re-renders the segment list
}

function _updateSplitConfirmState() {
  const btn = document.getElementById('btn-split-confirm');
  const action = document.querySelector('input[name="split-action"]:checked')?.value || 'partition';
  btn.classList.toggle('danger', action !== 'partition');
  btn.classList.toggle('primary', action === 'partition');
  const noPoints = _splitPoints.length === 0;
  btn.disabled = noPoints;
  btn.title = noPoints ? 'Place at least one split point first' : '';
  _renderSplitSegmentList();
}

function _renderSplitTimeline() {
  const bar      = document.getElementById('split-timeline-bar');
  const markers  = document.getElementById('split-markers-layer');
  const segments = document.getElementById('split-segments-layer');
  if (!bar) return;

  // Redraw waveform canvas in case width changed
  _drawWaveform();

  // Re-render overlay layers that depend on user markers (suggestion pins hide when near a marker)
  _renderSuggestionLayer();

  // Segment colour bands
  const pts = [0, ..._splitPoints, _splitDurationS];
  const palette = ['var(--accent)', 'var(--warning)', 'var(--green)', 'var(--red)'];
  segments.innerHTML = pts.slice(0, -1).map((start, i) => {
    const end      = pts[i + 1];
    const widthPct = ((end - start) / _splitDurationS * 100).toFixed(3);
    const col      = _splitIgnored.has(i) ? 'var(--muted)' : palette[i % palette.length];
    const opacity  = _splitIgnored.has(i) ? '0.08' : '0.12';
    return `<div style="height:100%;width:${widthPct}%;background:${col};opacity:${opacity};border-right:1px solid ${col}"></div>`;
  }).join('');

  // User-placed markers with drag handles
  markers.innerHTML = _splitPoints.map(p => {
    const pct = (p / _splitDurationS * 100).toFixed(3);
    const timeLabel = _fmtSplitTime(p);
    return `<div class="split-marker" style="position:absolute;left:${pct}%;top:0;bottom:0;width:10px;transform:translateX(-50%);cursor:ew-resize;pointer-events:auto;display:flex;align-items:stretch;justify-content:center"
                 title="${timeLabel} - drag to move, click to preview from here"
                 onpointerdown="event.stopPropagation();_splitMarkerPointerDown(event,${p})">
               <div style="width:2px;background:var(--accent);border-radius:1px"></div>
               <button type="button" class="split-marker-x" title="Remove split point"
                       aria-label="Remove split point at ${timeLabel}"
                       onpointerdown="event.stopPropagation()"
                       onclick="event.stopPropagation();_removeSplitPoint(${p},false)">&#215;</button>
             </div>`;
  }).join('');
}

function _parseSplitTime(str) {
  const parts = str.trim().split(':').map(Number);
  if (parts.some(isNaN)) return null;
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 1) return parts[0];
  return null;
}

function _updateSplitPoint(idx, timeStr, onRerender) {
  const sec = _parseSplitTime(timeStr);
  if (sec === null) {
    showToast(`Couldn't read "${timeStr}" - use h:mm:ss or m:ss`, 'error');
    onRerender();
    return;
  }
  if (sec <= 0 || sec >= _splitDurationS) {
    showToast(`Split point must be between 0:00 and ${_fmtSplitTime(_splitDurationS)}`, 'error');
    onRerender();
    return;
  }
  _splitPoints[idx] = sec;
  _splitPoints.sort((a, b) => a - b);
  if (_splitVideoId) _rebuildSplitNames(); else _rebuildPreSplitNames();
  onRerender();
}

function _renderSegmentList(listId, onRerender, showPlayBtn, showIgnore = true) {
  const list = document.getElementById(listId);
  if (!list || !_splitDurationS) return;
  const pts = [0, ..._splitPoints, _splitDurationS];

  list.innerHTML = pts.slice(0, -1).map((start, i) => {
    const end      = pts[i + 1];
    const ignored  = _splitIgnored.has(i);
    const name     = escHtml(_splitNames[i] || `Part ${i + 1}`);
    const startStr = escHtml(_fmtSplitTime(start));
    const endStr   = escHtml(_fmtSplitTime(end));
    const onUpdate = `_updateSplitPoint(%idx%, this.value, ${onRerender.name})`;
    const dimStyle = ignored ? 'opacity:0.45;' : '';
    const startEl  = i === 0
      ? `<span style="font-size:12px;color:var(--muted);min-width:58px">${startStr}</span>`
      : `<input type="text" value="${startStr}"
               style="font-size:12px;color:var(--muted);background:transparent;border:none;border-bottom:1px dashed var(--muted);width:58px;text-align:center;padding:1px 2px"
               title="Edit split point (h:mm:ss or m:ss)"
               onchange="${onUpdate.replace('%idx%', i - 1)}"
               aria-label="Segment ${i + 1} start time">`;
    const endEl    = i === pts.length - 2
      ? `<span style="font-size:12px;color:var(--muted);min-width:58px">${endStr}</span>`
      : `<input type="text" value="${endStr}"
               style="font-size:12px;color:var(--muted);background:transparent;border:none;border-bottom:1px dashed var(--muted);width:58px;text-align:center;padding:1px 2px"
               title="Edit split point (h:mm:ss or m:ss)"
               onchange="${onUpdate.replace('%idx%', i)}"
               aria-label="Segment ${i + 1} end time">`;
    const playBtn  = showPlayBtn
      ? `<button class="btn ghost" style="padding:2px 7px;font-size:12px;flex-shrink:0" title="Play from ${startStr}" onclick="_splitSeekTo(${start})">&#9654;</button>`
      : '';
    const ignoreChk = showIgnore ? `<label style="display:flex;align-items:center;gap:4px;font-size:12px;color:var(--muted);white-space:nowrap;cursor:pointer;flex-shrink:0" title="Ignore this segment - it will be split off but not analyzed">
        <input type="checkbox" ${ignored ? 'checked' : ''} onchange="_toggleIgnored(${i}, ${onRerender.name})"> Ignore
      </label>` : '';
    return `
      <div style="display:flex;align-items:center;gap:10px;padding:6px 10px;background:var(--surface);border:1px solid var(--border);border-radius:6px;${ignored ? 'opacity:0.5' : ''}">
        ${playBtn}
        <div style="display:flex;align-items:center;gap:4px;white-space:nowrap;${dimStyle}">${startEl}<span style="font-size:12px;color:var(--muted)">–</span>${endEl}</div>
        <input type="text" value="${name}"
               style="flex:1;padding:4px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px"
               onchange="_splitNames[${i}] = this.value"
               ${ignored ? 'disabled' : ''}
               aria-label="Segment ${i + 1} name">
        ${ignoreChk}
      </div>`;
  }).join('');
}

function _toggleIgnored(idx, onRerender) {
  if (_splitIgnored.has(idx)) _splitIgnored.delete(idx);
  else _splitIgnored.add(idx);
  onRerender();
}

function _renderSplitSegmentList() {
  const action = document.querySelector('input[name="split-action"]:checked')?.value || 'partition';
  // Ignore only matters when segments get reanalyzed independently - meaningless
  // for a plain partition, where every segment keeps whatever clips land in it.
  _renderSegmentList('split-segment-list', _renderSplitEditor, true, action !== 'partition');
}

function _fmtSplitTime(sec) {
  const s  = Math.round(sec);
  const h  = Math.floor(s / 3600);
  const m  = Math.floor((s % 3600) / 60);
  const ss = s % 60;
  if (h) return `${h}:${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;
  return `${m}:${String(ss).padStart(2,'0')}`;
}

// ── confirm ───────────────────────────────────────────────────────────────────

function confirmSplit() {
  const action = document.querySelector('input[name="split-action"]:checked')?.value || 'partition';
  if (action === 'partition') {
    _doSplitPartitionOnly();
    return;
  }
  const keepExported     = action === 'reanalyze-keep';
  const video            = AppState.videos.find(v => v.id === _splitVideoId);
  const clipCount        = video?.clip_count ?? _splitClipRanges.length;
  const exportedCount    = video?.exported ?? 0;
  const analyzedSegments = _splitPoints.length + 1 - _splitIgnored.size;
  const consequence = keepExported
    ? `This deletes ${plural(Math.max(0, clipCount - exportedCount), 'unexported clip')} (keeping ${plural(exportedCount, 'exported clip')}) and runs analysis fresh on ${plural(analyzedSegments, 'segment')}.`
    : `This deletes all ${plural(clipCount, 'existing clip')} and runs analysis fresh on ${plural(analyzedSegments, 'segment')}.`;
  showConfirm(
    'Delete clips and re-analyze?',
    consequence,
    'Delete & Re-analyze',
    () => _doSplitAndReanalyze(keepExported),
    true,
  );
}

async function _doSplitPartitionOnly() {
  if (!_splitVideoId) return;

  const btn = document.getElementById('btn-split-confirm');
  btn.disabled = true;
  btn.textContent = 'Splitting…';

  try {
    const res = await fetch(`/api/videos/${_splitVideoId}/split`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({split_points: _splitPoints, segment_names: _splitNames, migrate_clips: true}),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(formatApiError(err));
    }
    const data = await res.json();
    showToast(
      `Recording split into ${plural(data.segment_ids.length, 'segment')} ` +
      ` -  ${plural(data.migrated_clips, 'clip')} moved over`
    );
    closeSplitEditor();
    await loadVideos();
  } catch (err) {
    showToast(`Split failed: ${err.message}`, 'error');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Confirm';
  }
}

async function _doSplitAndReanalyze(keepExported) {
  if (!_splitVideoId) return;

  const parentVideo     = AppState.videos.find(v => v.id === _splitVideoId);
  const reanalyzeParams = await _reanalyzeParams(parentVideo);

  const btn = document.getElementById('btn-split-confirm');
  btn.disabled = true;
  btn.textContent = 'Splitting…';

  let segmentIds;
  try {
    const splitRes = await fetch(`/api/videos/${_splitVideoId}/split`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({split_points: _splitPoints, segment_names: _splitNames}),
    });
    if (!splitRes.ok) {
      const err = await splitRes.json().catch(() => ({}));
      throw new Error(formatApiError(err));
    }
    segmentIds = (await splitRes.json()).segment_ids;
  } catch (err) {
    showToast(`Split failed: ${err.message}`, 'error');
    btn.disabled = false;
    btn.textContent = 'Confirm';
    return;
  }

  // Filter out ignored segments - they are split off but not analyzed
  const activeIds = segmentIds.filter((_, i) => !_splitIgnored.has(i));

  // Clear existing clips on each active segment before reanalyzing
  for (const segId of activeIds) {
    const clearRes = await fetch(`/api/videos/${segId}/clips/clear`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({keep_exported: keepExported}),
    });
    if (!clearRes.ok) {
      showToast(`Failed to clear clips on segment ${segId}`, 'error');
      btn.disabled = false;
      btn.textContent = 'Confirm';
      return;
    }
  }

  closeSplitEditor();
  openLog();
  _reanalyzeSegmentsSequentially(activeIds, 0, reanalyzeParams);
}

async function _reanalyzeSegmentsSequentially(segmentIds, index, params) {
  if (index >= segmentIds.length) {
    loadVideos().then(() =>
      showToast(`Reanalysis complete - ${plural(segmentIds.length, 'segment')}`)
    );
    return;
  }
  await _waitWhileAnalyzePaused();
  const segId = segmentIds[index];
  fetch('/api/analyze/start', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({video_id: segId, ...params}),
  }).then(res => {
    if (!res.ok) {
      res.json().catch(() => ({})).then(err => {
        showToast(formatApiError(err) || `Failed to start analysis for segment ${segId}`, 'error');
      });
      return;
    }
    appendLog(`Analyzing segment ${index + 1}/${segmentIds.length}…`);
    streamSSE(
      '/api/analyze/events',
      () => { loadVideos(); _reanalyzeSegmentsSequentially(segmentIds, index + 1, params); },
      INGEST_STEPS,
      `Segment ${index + 1}/${segmentIds.length}`,
      false,
      null,
      true,
    );
  }).catch(err => showToast(netErrMsg(err), 'error'));
}

// ── pre-analysis split editor (inline in New Recording panel) ─────────────────

function onPreSplitToggle(checked) {
  if (checked && _splitDurationS > 0) {
    _openPreSplitEditor();
  } else {
    _closePreSplitEditor();
  }
}

function initPreSplitDuration(durationS) {
  _splitDurationS = durationS;
  _splitPoints    = [];
  _splitNames     = [];
  const section = document.getElementById('pre-split-section');
  if (section) section.style.display = '';
  const toggle = document.getElementById('pre-split-toggle');
  if (toggle && toggle.checked) _openPreSplitEditor();
}

function hidePreSplitSection() {
  _splitDurationS = 0;
  _splitPoints    = [];
  _splitNames     = [];
  const section = document.getElementById('pre-split-section');
  if (section) section.style.display = 'none';
  _closePreSplitEditor();
  const toggle = document.getElementById('pre-split-toggle');
  if (toggle) toggle.checked = false;
}

function _openPreSplitEditor() {
  _splitPoints = [];
  _splitNames  = [];
  const ed = document.getElementById('pre-split-editor');
  if (ed) ed.style.display = 'flex';
  _renderPreSplitEditor();
}

function _closePreSplitEditor() {
  const ed = document.getElementById('pre-split-editor');
  if (ed) ed.style.display = 'none';
}

function _rebuildPreSplitNames() {
  const count = _splitPoints.length + 1;
  _splitNames = Array.from({length: count}, (_, i) => `Part ${i + 1}`);
}

function _renderPreSplitEditor() {
  _renderPreSplitTimeline();
  _renderPreSplitSegmentList();
}

function _renderPreSplitTimeline() {
  const markers  = document.getElementById('pre-split-markers-layer');
  const segments = document.getElementById('pre-split-segments-layer');
  if (!markers || !_splitDurationS) return;

  const pts     = [0, ..._splitPoints, _splitDurationS];
  const palette = ['var(--accent)', 'var(--warning)', 'var(--green)', 'var(--red)'];
  segments.innerHTML = pts.slice(0, -1).map((start, i) => {
    const end      = pts[i + 1];
    const widthPct = ((end - start) / _splitDurationS * 100).toFixed(3);
    const col      = palette[i % palette.length];
    return `<div style="height:100%;width:${widthPct}%;background:${col};opacity:0.12;border-right:1px solid ${col}"></div>`;
  }).join('');

  markers.innerHTML = _splitPoints.map(p => {
    const pct = (p / _splitDurationS * 100).toFixed(3);
    const timeLabel = _fmtSplitTime(p);
    return `<div class="split-marker" style="position:absolute;left:${pct}%;top:0;bottom:0;width:10px;transform:translateX(-50%);cursor:ew-resize;pointer-events:auto;display:flex;align-items:stretch;justify-content:center"
                 title="${timeLabel} - drag to move"
                 onpointerdown="event.stopPropagation();_preSplitMarkerPointerDown(event,${p})">
               <div style="width:2px;background:var(--accent);border-radius:1px"></div>
               <button type="button" class="split-marker-x" title="Remove split point"
                       aria-label="Remove split point at ${timeLabel}"
                       onpointerdown="event.stopPropagation()"
                       onclick="event.stopPropagation();_removeSplitPoint(${p},true)">&#215;</button>
             </div>`;
  }).join('');
}

function _renderPreSplitSegmentList() {
  _renderSegmentList('pre-split-segment-list', _renderPreSplitEditor, false);
}

function preSplitTimelineClick(e) {
  if (!_splitDurationS || _dragActive) return;
  const bar  = document.getElementById('pre-split-timeline-bar');
  const rect = bar.getBoundingClientRect();
  const frac = (e.clientX - rect.left) / rect.width;
  const sec  = Math.round(frac * _splitDurationS * 10) / 10;

  if (sec <= 0 || sec >= _splitDurationS) return;

  const threshold = _splitDurationS * 0.005;
  if (_splitPoints.some(p => Math.abs(p - sec) <= threshold)) return;

  _splitPoints.push(sec);
  _splitPoints.sort((a, b) => a - b);
  _rebuildPreSplitNames();
  _renderPreSplitEditor();
}

function _preSplitMarkerPointerDown(e, sec) {
  e.stopPropagation();
  e.preventDefault();
  _dragMarkerSec = sec;
  _dragActive    = true;

  const bar = document.getElementById('pre-split-timeline-bar');

  function onMove(ev) {
    if (!_dragActive) return;
    const rect   = bar.getBoundingClientRect();
    const frac   = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width));
    const newSec = Math.round(frac * _splitDurationS * 10) / 10;
    if (newSec <= 0 || newSec >= _splitDurationS) return;
    const idx = _splitPoints.indexOf(_dragMarkerSec);
    if (idx !== -1) {
      _splitPoints[idx] = newSec;
      _dragMarkerSec    = newSec;
      _splitPoints.sort((a, b) => a - b);
      _renderPreSplitEditor();
    }
  }

  function onUp() {
    _dragActive    = false;
    _dragMarkerSec = null;
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup',   onUp);
    _rebuildPreSplitNames();
    _renderPreSplitEditor();
  }

  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup',   onUp);
}

Object.assign(window, {
  isSplitEditorOpen, openSplitEditor, closeSplitEditor, _teardownSplitEditor,
  _splitSeekTo, _generateWaveform, _computeSuggestionPins, _setSplitZoom,
  _promoteSuggestionPin, _splitMarkerPointerDown, splitTimelineClick,
  _removeSplitPoint, _updateSplitPoint, _updateSplitConfirmState, _parseSplitTime,
  _toggleIgnored, _fmtSplitTime, _renderSplitEditor, _renderPreSplitEditor,
  confirmSplit, onPreSplitToggle, initPreSplitDuration, hidePreSplitSection,
  preSplitTimelineClick, _preSplitMarkerPointerDown,
});
})();

//# sourceURL=voices.js
(function () {
// Feature-map - People / project-wide speaker identity (code: ProjectVoice; UI "Person"/"People").
//   API: routes/voices.py · Tests: tests/ui/test_ui_voices.py
// ── People view (PanelNav takeover) ────────────────────────────────────────────
// A project-level view listing every Person (a voice named once, applied across all
// recordings). Lists each Person's member recordings, pending cross-recording
// suggestions (confirm/dismiss inline), and rename/recolor/merge/split. Naming a
// Person here flows to every linked recording's captions/excerpts/exports because the
// server resolves display_name through the linked voice.

function isPeopleOpen() {
  return PanelNav.isOpen('people');
}

function openPeopleView() {
  PanelNav.open({
    id: 'people',
    title: 'People',
    render: container => _peopleMount(container),
    isDirty: () => false,
    onClose: () => {},
  });
}

function _peopleMount(container) {
  container.innerHTML = `
    <div class="people-header">
      <p class="people-intro">A <strong>Person</strong> is one voice named once and applied across
        every recording. Name a Person here and the name shows up wherever that voice speaks.</p>
      <button class="btn ghost" id="people-backfill-btn"
              title="Group the speakers you have already named across recordings into people. Nothing is renamed - results appear here for you to review.">Find people across recordings</button>
    </div>
    <div id="people-list"><div class="transcript-empty">Loading&hellip;</div></div>`;
  container.addEventListener('click', _onPeopleClick);
  container.addEventListener('change', _onPeopleChange);
  _loadPeople();
}

let _peopleCache = [];
let _charactersCache = [];

async function _loadPeople() {
  const list = document.getElementById('people-list');
  if (!list) return;
  try {
    const [voices, chars] = await Promise.all([
      fetch('/api/voices').then(r => r.json()),
      fetch('/api/characters').then(r => r.json()).catch(() => []),
    ]);
    _peopleCache = Array.isArray(voices) ? voices : [];
    _charactersCache = Array.isArray(chars) ? chars : [];
    _renderPeople();
  } catch (_) {
    list.innerHTML = '<div class="transcript-empty">Could not load people.</div>';
  }
}

function _renderPeople() {
  const list = document.getElementById('people-list');
  if (!list) return;
  if (!_peopleCache.length) {
    list.innerHTML = `<div class="transcript-empty">No people yet. Open a recording's
      <strong>Speakers</strong> panel and choose <strong>Promote to Person</strong> on a named
      speaker to start.</div>`;
    return;
  }
  list.innerHTML = _peopleCache.map(_personCardHtml).join('');
  list.querySelectorAll('.voice-color-input').forEach(el => window.ColorPicker?.attach(el));
}

function _personCardHtml(voice) {
  return `
    <div class="person-card" data-voice-id="${voice.id}">
      <div class="person-head">
        <input class="voice-color-input" type="color" data-voice-id="${voice.id}"
               value="${escHtml(voice.color)}" title="Caption color for this person"
               aria-label="Caption color for ${escHtml(voice.display_name)}">
        <input class="voice-name-input" type="text" data-voice-id="${voice.id}"
               value="${escHtml(voice.name || '')}" placeholder="Name this person&hellip;"
               aria-label="Name for ${escHtml(voice.display_name)}" maxlength="60">
        <span class="person-count">${plural(voice.member_count, 'recording')}</span>
        ${_mergeControlHtml(voice)}
      </div>
      ${_membersHtml(voice)}
      ${_characterControlHtml(voice)}
      ${_suggestionsHtml(voice)}
    </div>`;
}

// Optional overlay: link this Person to a world-context Character (lore + scoring
// boost). A project with no characters and no existing link shows no picker at all,
// so a zero-context workflow is visually unchanged.
function _characterControlHtml(voice) {
  const linkedId = voice.character ? voice.character.id : null;
  if (!_charactersCache.length && linkedId == null) return '';
  return `
    <div class="person-character">
      <label class="person-character-label" for="voice-char-${voice.id}">Character</label>
      <select class="voice-character-select" id="voice-char-${voice.id}" data-voice-id="${voice.id}"
              aria-label="World-context character for ${escHtml(voice.display_name)}">
        ${_characterOptions(voice.character)}
      </select>
    </div>`;
}

function _characterOptions(linked) {
  const selectedId = linked ? linked.id : null;
  const byContext = new Map();
  for (const c of _charactersCache) {
    const key = c.context_name || c.context_slug;
    if (!byContext.has(key)) byContext.set(key, []);
    byContext.get(key).push(c);
  }
  let html = `<option value="">No character</option>`;
  // If the linked character isn't in the loaded list (e.g. /api/characters failed to
  // load), still render it as the selected option from the Person's own data - otherwise
  // an existing link shows as "No character", which a subsequent save would clear.
  if (selectedId != null && !_charactersCache.some(c => c.id === selectedId)) {
    html += `<option value="${selectedId}" selected>${escHtml(linked.name || 'Linked character')}</option>`;
  }
  for (const [ctxName, chars] of byContext) {
    html += `<optgroup label="${escHtml(ctxName)}">`
          + chars.map(c => `<option value="${c.id}"${c.id === selectedId ? ' selected' : ''}>${escHtml(c.name)}</option>`).join('')
          + `</optgroup>`;
  }
  return html;
}

function _mergeControlHtml(voice) {
  const others = _peopleCache.filter(v => v.id !== voice.id);
  if (!others.length) return '';
  const opts = others.map(v =>
    `<option value="${v.id}">${escHtml(v.display_name)}</option>`).join('');
  return `
    <select class="voice-merge-select" data-voice-id="${voice.id}"
            aria-label="Merge another person into ${escHtml(voice.display_name)}">
      <option value="">Merge in&hellip;</option>${opts}
    </select>`;
}

function _membersHtml(voice) {
  if (!voice.members.length) {
    return '<div class="person-empty">No recordings linked yet.</div>';
  }
  const rows = voice.members.map(m => `
    <div class="person-member">
      <span class="person-member-name">${escHtml(m.display_name)}</span>
      <span class="person-member-file" title="${escHtml(m.video_filename)}">${escHtml(m.video_filename)}</span>
      <button class="btn ghost voice-detach-btn" data-voice-id="${voice.id}" data-speaker-id="${m.speaker_id}"
              title="Remove this recording's voice from ${escHtml(voice.display_name)}">Remove</button>
    </div>`).join('');
  return `<div class="person-members">${rows}</div>`;
}

function _suggestionsHtml(voice) {
  if (!voice.suggestions || !voice.suggestions.length) return '';
  const rows = voice.suggestions.map(s => `
    <div class="person-suggestion">
      <span class="person-member-file" title="${escHtml(s.video_filename)}">${escHtml(s.video_filename)}</span>
      <span class="person-suggestion-score">${Math.round((s.score || 0) * 100)}% voice match</span>
      <button class="btn primary voice-confirm-btn" data-speaker-id="${s.speaker_id}"
              title="Confirm this recording's voice is ${escHtml(voice.display_name)}">Same person</button>
      <button class="btn ghost voice-reject-btn" data-speaker-id="${s.speaker_id}"
              title="Not the same person">Not them</button>
    </div>`).join('');
  return `
    <div class="person-suggestions">
      <div class="person-suggestions-head">Possible matches from other recordings</div>
      ${rows}
    </div>`;
}

function _onPeopleClick(e) {
  if (e.target.closest('#people-backfill-btn')) {
    _backfillPeople(e.target.closest('#people-backfill-btn'));
    return;
  }
  const detach = e.target.closest('.voice-detach-btn');
  if (detach) {
    _splitPerson(parseInt(detach.dataset.voiceId, 10), parseInt(detach.dataset.speakerId, 10));
    return;
  }
  const confirmBtn = e.target.closest('.voice-confirm-btn');
  if (confirmBtn) {
    _resolveSuggestion(parseInt(confirmBtn.dataset.speakerId, 10), true);
    return;
  }
  const rejectBtn = e.target.closest('.voice-reject-btn');
  if (rejectBtn) {
    _resolveSuggestion(parseInt(rejectBtn.dataset.speakerId, 10), false);
  }
}

function _onPeopleChange(e) {
  const nameInput = e.target.closest('.voice-name-input');
  if (nameInput) {
    _saveVoice(parseInt(nameInput.dataset.voiceId, 10), {name: nameInput.value.trim()});
    return;
  }
  const colorInput = e.target.closest('.voice-color-input');
  if (colorInput) {
    _saveVoice(parseInt(colorInput.dataset.voiceId, 10), {color: colorInput.value});
    return;
  }
  const mergeSelect = e.target.closest('.voice-merge-select');
  if (mergeSelect && mergeSelect.value) {
    _mergePerson(parseInt(mergeSelect.dataset.voiceId, 10), parseInt(mergeSelect.value, 10));
    return;
  }
  const charSelect = e.target.closest('.voice-character-select');
  if (charSelect) {
    _setPersonCharacter(parseInt(charSelect.dataset.voiceId, 10),
      charSelect.value ? parseInt(charSelect.value, 10) : null);
  }
}

async function _setPersonCharacter(voiceId, characterId) {
  try {
    const res = await fetch(`/api/voices/${voiceId}/character`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({character_id: characterId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast(characterId ? 'Character linked' : 'Character unlinked');
    await _loadPeople();
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

async function _saveVoice(voiceId, body) {
  try {
    const res = await fetch(`/api/voices/${voiceId}`, {
      method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const updated = await res.json();
    if ('name' in body) showToast(updated.is_named ? `Named ${updated.display_name}` : 'Name cleared');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not save: ${err.message}`, 'error');
  }
}

async function _mergePerson(targetId, otherId) {
  const other = _peopleCache.find(v => v.id === otherId);
  const target = _peopleCache.find(v => v.id === targetId);
  showConfirm(
    'Merge people?',
    `Merge ${other ? other.display_name : 'that person'} into ${target ? target.display_name : 'this person'}? `
      + 'Their recordings move over and the other person is removed.',
    'Merge',
    async () => {
      try {
        const res = await fetch(`/api/voices/${targetId}/merge`, {
          method: 'POST', headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({other_id: otherId}),
        });
        if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
        showToast('People merged');
        await _loadPeople();
        _syncOpenRecording();
      } catch (err) {
        showToast(`Could not merge: ${err.message}`, 'error');
      }
    },
  );
  await _loadPeople();  // reset the select whether or not they confirm
}

async function _splitPerson(voiceId, speakerId) {
  try {
    const res = await fetch(`/api/voices/${voiceId}/split`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({speaker_id: speakerId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast('Recording removed from this person');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

async function _resolveSuggestion(speakerId, same) {
  const endpoint = same ? 'confirm-voice' : 'reject-voice';
  try {
    const res = await fetch(`/api/speakers/${speakerId}/${endpoint}`, {method: 'POST'});
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast(same ? 'Confirmed - same person' : 'Kept separate');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

async function _backfillPeople(btn) {
  if (btn) { btn.disabled = true; btn.textContent = 'Finding…'; }
  try {
    const res = await fetch('/api/voices/backfill', {method: 'POST'});
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const data = await res.json();
    showToast(data.created
      ? `Found ${plural(data.created, 'person')} to review`
      : 'No new people found across your recordings');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not find people: ${err.message}`, 'error');
  } finally {
    if (btn && document.body.contains(btn)) { btn.disabled = false; btn.textContent = 'Find people across recordings'; }
  }
}

// A People-view change can alter a display name in the currently open recording -
// refresh its Speakers card, transcript, and clip so it doesn't show a stale name.
function _syncOpenRecording() {
  const videoId = AppState.activeVideoId;
  if (videoId != null && window.loadSpeakers) loadSpeakers(videoId);
  if (videoId != null && window.reloadVideoTranscriptIfOpen) reloadVideoTranscriptIfOpen(videoId);
  if (AppState.activeClipId != null && window.selectClip) selectClip(AppState.activeClipId);
}

Object.assign(window, {openPeopleView, isPeopleOpen});
})();

//# sourceURL=transcript.js
(function () {
// Feature-map - Transcript views + click-to-edit captions (code: TranscriptSegment).
//   API: routes/videos.py, routes/scoring.py · Tests: tests/ui/test_ui_transcript.py, tests/integration/test_transcript_edit.py
// ── timed transcript views ────────────────────────────────────────────────────
// Per-line transcript for a clip (clip-relative time) and for a whole recording
// (absolute time), each line with a ▶ that seeks the visible player. Works for
// diarized transcripts (speaker name shown when it changes) and plain ones
// (each caption segment becomes its own line). Each line's text is click-to-edit
// so mis-heard names/jargon can be fixed before re-scoring.

function seekPlayerTo(seconds) {
  const video = document.querySelector('#player-area video');
  if (!video) return;
  video.currentTime = Math.max(0, seconds || 0);
  const attempt = video.play();
  if (attempt && attempt.catch) attempt.catch(() => {});
}

function _clock(ms) {
  const total = Math.max(0, Math.round((ms || 0) / 1000));
  const s = total % 60;
  const m = Math.floor(total / 60) % 60;
  const h = Math.floor(total / 3600);
  const mm = String(m).padStart(2, '0');
  const ss = String(s).padStart(2, '0');
  return h ? `${h}:${mm}:${ss}` : `${m}:${ss}`;
}

// opts.seekOffsetS is added to each line's play target - 0 for a clip (its player
// is trimmed to the clip) and the segment start for a split recording (whose player
// streams the untrimmed parent file). opts.videoId enables the per-line speaker
// control (rename / reassign); omit it to render a read-only transcript. opts.readOnly
// suppresses the click-to-edit-caption affordance even when a line carries a seg_id -
// used by the manual clip picker, where a line click selects a range instead.
function renderTranscriptLines(lines, opts) {
  opts = opts || {};
  const offsetS = opts.seekOffsetS || 0;
  const videoId = opts.videoId;
  const readOnly = !!opts.readOnly;
  if (!Array.isArray(lines) || !lines.length) {
    return '<div class="transcript-empty">No transcript available.</div>';
  }
  let prevSpeaker = null;
  const rows = lines.map(line => {
    const showSpeaker = line.speaker && line.speaker !== prevSpeaker;
    prevSpeaker = line.speaker;
    const colorAttr = line.color ? ` style="color:${escHtml(line.color)}"` : '';
    const speaker = showSpeaker
      ? `<div class="tline-speaker"${colorAttr}>${escHtml(line.speaker)}</div>`
      : '';
    const clock = _clock(line.start_ms);
    const seekS = (line.start_ms || 0) / 1000 + offsetS;
    const editable = !readOnly && line.seg_id != null;
    const editAttrs = editable
      ? ` data-seg-id="${line.seg_id}" role="button" tabindex="0" title="Click to edit caption"`
      : '';
    // display_color is always set server-side; var(--muted) is a defensive fallback so
    // no hardcoded hex ever ships (no-hardcoded-colors rule).
    const dotColor = line.color ? escHtml(line.color) : 'var(--muted)';
    const spkName = line.speaker ? escHtml(line.speaker) : 'this speaker';
    const spk = (videoId != null && line.speaker_id != null)
      ? `<button class="tline-spk${line.speaker_edited ? ' edited' : ''}"
                 data-seg-id="${line.seg_id}" data-speaker-id="${line.speaker_id}" data-video-id="${videoId}"
                 title="${line.speaker_edited ? 'Reassigned by you - ' : ''}${spkName} - click to change or rename"
                 aria-label="Change or rename speaker">
           <span class="tline-spk-dot" style="background:${dotColor}"></span></button>`
      : '';
    return `${speaker}<div class="tline" data-start-ms="${line.start_ms || 0}" data-end-ms="${line.end_ms || 0}"
      data-seg-id="${line.seg_id != null ? line.seg_id : ''}" data-speaker-id="${line.speaker_id != null ? line.speaker_id : ''}">
      <button class="tline-play" data-seek-s="${seekS}"
              title="Jump to ${clock}" aria-label="Play from ${clock}">&#9654;</button>
      <span class="tline-time">${clock}</span>
      ${spk}
      <span class="tline-text${editable ? ' editable' : ''}"${editAttrs}>${escHtml(line.text)}</span>
    </div>`;
  }).join('');
  return `<div class="transcript-lines">${rows}</div>`;
}

async function loadClipTranscript(clipId) {
  const el = document.getElementById('clip-transcript-view');
  if (!el) return;
  try {
    const data = await fetch(`/api/clips/${clipId}/transcript`).then(r => r.json());
    if (data.lines && data.lines.length) {
      el.innerHTML = renderTranscriptLines(data.lines, {videoId: AppState.activeVideoId});
    }
    // else: keep the plain excerpt already rendered as a fallback.
  } catch (_) {
    // Leave the excerpt fallback in place on error.
  }
}

let _videoTranscriptLoadedFor = null;
async function loadVideoTranscript(videoId) {
  const el = document.getElementById('video-transcript-view');
  if (!el) return;
  // Skip the fetch only when this video's transcript is still rendered. A bare
  // videoId match isn't enough: renderVideoDetail rebuilds #detail, leaving a
  // fresh empty #video-transcript-view while the flag still points here - that
  // combination is what left the panel silently blank on reopen.
  if (_videoTranscriptLoadedFor === videoId && el.childElementCount > 0) return;
  el.innerHTML = '<div class="transcript-empty">Loading…</div>';
  try {
    const data = await fetch(`/api/videos/${videoId}/transcript`).then(r => r.json());
    _resetLineSelect();
    const tools = (data.lines && data.lines.length) ? _lineMoveToolbar() : '';
    el.innerHTML = tools + renderTranscriptLines(data.lines, {seekOffsetS: data.seek_offset_s || 0, videoId});
    _videoTranscriptLoadedFor = videoId;
  } catch (_) {
    el.innerHTML = '<div class="transcript-empty">Could not load transcript.</div>';
  }
}

// ── multi-select "move lines to a speaker" (bulk split) ────────────────────────
// A selection mode on the full-recording transcript: pick several lines, then move
// them onto another speaker, a new one, or Unassigned in a single bulk call per source
// speaker (rebuilds excerpts + refreshes sidecars once). Only the recording transcript
// gets this - clip transcripts render without the toolbar.
const _lineMove = { videoId: null, active: false, selected: new Set() };

function _resetLineSelect() {
  _lineMove.active = false;
  _lineMove.selected = new Set();
}

function _lineMoveToolbar() {
  return `<div class="tx-move-bar" id="tx-move-bar">
    <button class="btn ghost tx-move-toggle" title="Select several lines and move them onto another speaker">Select lines to move</button>
  </div>`;
}

function _currentTranscriptVideoId() {
  const card = document.getElementById('video-transcript-details');
  return card ? parseInt(card.dataset.videoId, 10) : null;
}

async function _enterLineSelect() {
  _lineMove.videoId = _currentTranscriptVideoId();
  if (_lineMove.videoId == null) return;
  _lineMove.active = true;
  _lineMove.selected = new Set();
  document.getElementById('video-transcript-view')?.classList.add('select-mode');
  await _renderMoveBar();
}

function _exitLineSelect() {
  _resetLineSelect();
  const view = document.getElementById('video-transcript-view');
  if (view) {
    view.classList.remove('select-mode');
    view.querySelectorAll('.tline-selected').forEach(r => r.classList.remove('tline-selected'));
  }
  _renderMoveBar();
}

async function _renderMoveBar() {
  const bar = document.getElementById('tx-move-bar');
  if (!bar) return;
  if (!_lineMove.active) {
    bar.innerHTML = `<button class="btn ghost tx-move-toggle" title="Select several lines and move them onto another speaker">Select lines to move</button>`;
    return;
  }
  const speakers = await _getVideoSpeakers(_lineMove.videoId);
  const opts = speakers.map(s => `<option value="${s.id}">${escHtml(s.display_name)}</option>`).join('');
  bar.innerHTML = `
    <span class="tx-move-count">${plural(_lineMove.selected.size, 'line')} selected</span>
    <select class="tx-move-target" aria-label="Move selected lines to">
      <option value="">Move to&hellip;</option>${opts}
      <option value="__new__">+ New speaker</option>
      <option value="__none__">Unassigned</option>
    </select>
    <button class="btn ghost tx-move-cancel">Cancel</button>`;
}

function _toggleLineSelection(row) {
  const segId = parseInt(row.dataset.segId, 10);
  if (!segId || !row.dataset.speakerId) return;  // only attributed lines can be moved
  if (_lineMove.selected.has(segId)) {
    _lineMove.selected.delete(segId);
    row.classList.remove('tline-selected');
  } else {
    _lineMove.selected.add(segId);
    row.classList.add('tline-selected');
  }
  const count = document.querySelector('.tx-move-count');
  if (count) count.textContent = `${plural(_lineMove.selected.size, 'line')} selected`;
}

async function _moveSelectedLines(value) {
  const segIds = [..._lineMove.selected];
  const videoId = _lineMove.videoId;
  if (!segIds.length) { showToast('Select some lines first', 'warning'); await _renderMoveBar(); return; }
  try {
    const target = await _resolveMoveTarget(value, videoId);
    // The bulk endpoint moves lines of ONE source speaker, so group the selection by
    // each line's current speaker and call once per group.
    const groups = {};
    for (const segId of segIds) {
      const row = document.querySelector(`#video-transcript-view .tline[data-seg-id="${segId}"]`);
      const src = row && row.dataset.speakerId;
      if (src && parseInt(src, 10) !== target) (groups[src] = groups[src] || []).push(segId);
    }
    let moved = 0;
    for (const [src, ids] of Object.entries(groups)) {
      const res = await fetch(`/api/speakers/${src}/reassign-segments`, {
        method: 'PUT', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({seg_ids: ids, target_speaker_id: target}),
      });
      if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
      moved += (await res.json()).reassigned;
    }
    showToast(moved ? `Moved ${plural(moved, 'line')}` : 'Those lines were already on that speaker');
    _exitLineSelect();
    _refreshAfterSpeakerChange(videoId, null);
  } catch (err) {
    showToast(`Could not move lines: ${err.message}`, 'error');
    await _renderMoveBar();
  }
}

async function _resolveMoveTarget(value, videoId) {
  if (value === '__none__') return null;
  if (value !== '__new__') return parseInt(value, 10);
  const res = await fetch(`/api/videos/${videoId}/speakers`, {
    method: 'POST', headers: {'Content-Type': 'application/json'}, body: '{}',
  });
  if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
  delete _videoSpeakersCache[videoId];
  return (await res.json()).id;
}

// Called after a speaker rename/recolor so the open recording transcript picks up
// the new label without a manual refresh. Clears the fetch-once cache and, if the
// full-transcript panel is expanded, reloads it in place.
function reloadVideoTranscriptIfOpen(videoId) {
  _videoTranscriptLoadedFor = null;
  const card = document.getElementById('video-transcript-details');
  if (card && !card.classList.contains('collapsed')) loadVideoTranscript(videoId);
}

// ── per-line speaker control (rename + reassign) ───────────────────────────────
// A transcript line's speaker dot opens a menu to reattribute that one line to a
// different speaker (or detach it) and to name the line's current speaker without
// leaving the transcript. Speaker lists are cached per video and invalidated on any
// change so a fresh menu always reflects renames.
const _videoSpeakersCache = {};

async function _getVideoSpeakers(videoId) {
  if (_videoSpeakersCache[videoId]) return _videoSpeakersCache[videoId];
  const list = await fetch(`/api/videos/${videoId}/speakers`).then(r => r.json()).catch(() => []);
  _videoSpeakersCache[videoId] = Array.isArray(list) ? list : [];
  return _videoSpeakersCache[videoId];
}

let _openSpkMenu = null;

function _closeSpeakerMenu() {
  if (_openSpkMenu) { _openSpkMenu.remove(); _openSpkMenu = null; }
  document.removeEventListener('click', _onDocClickSpkMenu, true);
  document.removeEventListener('keydown', _onKeydownSpkMenu, true);
}

function _onDocClickSpkMenu(e) {
  if (_openSpkMenu && !_openSpkMenu.contains(e.target)) _closeSpeakerMenu();
}

function _onKeydownSpkMenu(e) {
  if (e.key === 'Escape') { e.preventDefault(); _closeSpeakerMenu(); }
}

async function _openSpeakerMenu(chip) {
  _closeSpeakerMenu();
  const segId = parseInt(chip.dataset.segId, 10);
  const curId = chip.dataset.speakerId ? parseInt(chip.dataset.speakerId, 10) : null;
  const videoId = parseInt(chip.dataset.videoId, 10);
  if (!videoId) return;
  const speakers = await _getVideoSpeakers(videoId);
  const cur = speakers.find(s => s.id === curId);

  const items = speakers.map(s =>
    `<button class="spk-menu-item${s.id === curId ? ' active' : ''}" data-reassign="${s.id}">
       <span class="spk-dot" style="background:${escHtml(s.color)}"></span>${escHtml(s.display_name)}</button>`
  ).join('');

  const menu = document.createElement('div');
  menu.className = 'spk-menu';
  menu.innerHTML = `
    <div class="spk-menu-head">Attribute this line to</div>
    ${items}
    <button class="spk-menu-item" data-reassign="">Unassigned</button>
    <button class="spk-menu-item spk-menu-new">+ New speaker</button>
    <div class="spk-menu-sep"></div>
    <div class="spk-menu-head">Name ${escHtml(cur ? cur.display_name : 'this speaker')}</div>
    <div class="spk-menu-rename">
      <input type="text" class="spk-menu-name" maxlength="60" placeholder="Add a name&hellip;"
             value="${escHtml(cur && cur.name ? cur.name : '')}">
      <button class="btn primary spk-menu-save">Save</button>
    </div>`;
  document.body.appendChild(menu);

  const rect = chip.getBoundingClientRect();
  const left = Math.max(8, Math.min(rect.left, window.innerWidth - menu.offsetWidth - 12));
  const top = Math.min(rect.bottom + 4, window.innerHeight - menu.offsetHeight - 8);
  menu.style.left = `${left}px`;
  menu.style.top = `${Math.max(8, top)}px`;
  _openSpkMenu = menu;

  menu.addEventListener('click', e => {
    if (e.target.closest('.spk-menu-new')) { _newSpeakerForLine(segId, videoId); return; }
    const reassign = e.target.closest('[data-reassign]');
    if (reassign) {
      const val = reassign.dataset.reassign;
      _reassignLine(segId, val === '' ? null : parseInt(val, 10), videoId);
      return;
    }
    if (e.target.closest('.spk-menu-save') && curId != null) {
      _renameSpeakerFromLine(curId, menu.querySelector('.spk-menu-name').value.trim(), videoId);
    }
  });
  menu.querySelector('.spk-menu-name')?.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); menu.querySelector('.spk-menu-save').click(); }
  });

  // Defer wiring the dismiss handlers so the click that opened the menu doesn't close it.
  setTimeout(() => {
    document.addEventListener('click', _onDocClickSpkMenu, true);
    document.addEventListener('keydown', _onKeydownSpkMenu, true);
  }, 0);
}

// Create a fresh unnamed speaker (for a voice diarization missed or merged) and move
// this line onto it. The user can name it from its dot afterward. Reassignment reuses
// the same path as picking an existing speaker (rebuilds excerpts, refreshes the card).
async function _newSpeakerForLine(segId, videoId) {
  try {
    const res = await fetch(`/api/videos/${videoId}/speakers`, {
      method: 'POST', headers: {'Content-Type': 'application/json'}, body: '{}',
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const speaker = await res.json();
    delete _videoSpeakersCache[videoId];
    await _reassignLine(segId, speaker.id, videoId);
    showToast(`Line moved to a new ${speaker.display_name}`);
  } catch (err) {
    showToast(`Could not add a speaker: ${err.message}`, 'error');
  }
}

async function _reassignLine(segId, speakerId, videoId) {
  try {
    const res = await fetch(`/api/transcript-segments/${segId}/speaker`, {
      method: 'PUT', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({speaker_id: speakerId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const data = await res.json();
    _closeSpeakerMenu();
    const n = (data.affected_clip_ids || []).length;
    showToast(n ? `Speaker reassigned - ${plural(n, 'clip')} affected; re-score to refresh` : 'Speaker reassigned');
    _refreshAfterSpeakerChange(videoId, data.affected_clip_ids);
  } catch (err) {
    showToast(`Could not reassign speaker: ${err.message}`, 'error');
  }
}

async function _renameSpeakerFromLine(speakerId, name, videoId) {
  try {
    const res = await fetch(`/api/speakers/${speakerId}`, {
      method: 'PUT', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name}),
    });
    if (!res.ok) throw new Error('save failed');
    const updated = await res.json();
    _closeSpeakerMenu();
    showToast(updated.is_named ? `Speaker named ${updated.display_name}` : 'Name cleared');
    _refreshAfterSpeakerChange(videoId, null);
  } catch (_) {
    showToast('Could not save speaker name', 'error');
  }
}

function _refreshAfterSpeakerChange(videoId, affectedClipIds) {
  delete _videoSpeakersCache[videoId];
  if (window.loadSpeakers) loadSpeakers(videoId);
  reloadVideoTranscriptIfOpen(videoId);
  const openClip = AppState.activeClipId;
  if (openClip != null && (affectedClipIds == null || affectedClipIds.includes(openClip))
      && window.refreshClipDetail) {
    refreshClipDetail(openClip);
  }
}

// ── inline caption editing ────────────────────────────────────────────────────
function startEditCaption(span) {
  if (span.classList.contains('editing')) return;
  const segId = span.dataset.segId;
  const original = span.textContent;
  span.classList.add('editing');
  span.innerHTML = '';

  const input = document.createElement('textarea');
  input.className = 'tline-edit-input';
  input.value = original;
  input.rows = Math.min(4, Math.max(1, Math.ceil(original.length / 48)));

  const actions = document.createElement('div');
  actions.className = 'tline-edit-actions';
  const save = document.createElement('button');
  save.className = 'btn primary';
  save.textContent = 'Save';
  const cancel = document.createElement('button');
  cancel.className = 'btn ghost';
  cancel.textContent = 'Cancel';
  actions.append(save, cancel);
  span.append(input, actions);
  input.focus();
  input.setSelectionRange(original.length, original.length);

  const restore = (text) => { span.classList.remove('editing'); span.textContent = text; };

  cancel.onclick = () => restore(original);
  input.onkeydown = ev => {
    if (ev.key === 'Escape') { ev.preventDefault(); restore(original); }
    else if (ev.key === 'Enter' && !ev.shiftKey) { ev.preventDefault(); save.click(); }
  };
  save.onclick = async () => {
    const text = input.value.trim();
    if (!text) { showToast('Caption cannot be empty', 'warning'); return; }
    if (text === original) { restore(original); return; }
    save.disabled = cancel.disabled = true;
    try {
      const res = await fetch(`/api/caption-segments/${segId}`, {
        method: 'PUT',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({text}),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(formatApiError(err));
      }
      const data = await res.json();
      restore(data.text);
      _onCaptionEdited(data);
    } catch (err) {
      save.disabled = cancel.disabled = false;
      showToast(`Could not save caption: ${err.message}`, 'error');
    }
  };
}

function _onCaptionEdited(data) {
  const affected = data.affected_clip_ids || [];
  showToast(affected.length
    ? `Caption updated - ${plural(affected.length, 'clip')} affected; re-score to refresh`
    : 'Caption updated');
  // Refresh the open clip's detail so its excerpt and the re-score notice update.
  const openId = AppState.activeClipId;
  if (openId && affected.includes(openId) && window.refreshClipDetail) refreshClipDetail(openId);
}

document.addEventListener('DOMContentLoaded', () => {
  const detail = document.getElementById('detail');
  if (!detail) return;
  detail.addEventListener('click', e => {
    if (e.target.closest('.tx-move-toggle')) { _enterLineSelect(); return; }
    if (e.target.closest('.tx-move-cancel')) { _exitLineSelect(); return; }
    const view = document.getElementById('video-transcript-view');
    if (view && view.classList.contains('select-mode') && view.contains(e.target)) {
      // In select mode a line click toggles selection; playback still works, but the
      // dot menu and caption editing yield to selection.
      const play = e.target.closest('.tline-play');
      if (play) { seekPlayerTo(parseFloat(play.dataset.seekS)); return; }
      const row = e.target.closest('.tline');
      if (row) { _toggleLineSelection(row); return; }
    }
    const spk = e.target.closest && e.target.closest('.tline-spk');
    if (spk) { e.stopPropagation(); _openSpeakerMenu(spk); return; }
    const text = e.target.closest && e.target.closest('.tline-text.editable');
    if (text) { startEditCaption(text); return; }
    const btn = e.target.closest && e.target.closest('.tline-play');
    if (btn) seekPlayerTo(parseFloat(btn.dataset.seekS));
  });
  detail.addEventListener('change', e => {
    const target = e.target.closest && e.target.closest('.tx-move-target');
    if (target && target.value) _moveSelectedLines(target.value);
  });
  detail.addEventListener('keydown', e => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const text = e.target.closest && e.target.closest('.tline-text.editable');
    if (text && !text.classList.contains('editing')) { e.preventDefault(); startEditCaption(text); }
  });
  // Lazy-load the full-video transcript the first time its collapsible card is
  // expanded (cardtoggle bubbles up from the card - see utils.js).
  detail.addEventListener('cardtoggle', e => {
    if (e.detail.key === 'video-transcript' && !e.detail.collapsed) {
      const card = document.getElementById('video-transcript-details');
      if (card) loadVideoTranscript(parseInt(card.dataset.videoId, 10));
    }
  });
});

Object.assign(window, {
  loadClipTranscript, loadVideoTranscript, reloadVideoTranscriptIfOpen,
  renderTranscriptLines, seekPlayerTo, startEditCaption,
});
})();

//# sourceURL=namecorrections.js
(function () {
// Feature-map - Name corrections (code: name_corrections; UI "Fix names").
//   API: routes/name_corrections.py · Tests: tests/ui/test_ui_namecorrections.py
// ── transcript name correction (Plan 09) ──────────────────────────────────────
// A PanelNav takeover launched from the recording's transcript card. Scans the
// transcript for likely mis-transcriptions of known names ("You" → "Yuu"),
// groups them by pattern, and applies only the instances the user keeps checked.
// Nothing is auto-applied; applying routes through the same caption-edit path as
// a manual edit, so staleness badges and sidecars behave identically.

let _ncVideoId = null;
let _ncData = null;  // last scan result - the source for offsets/replacements at apply time

function isNameCorrectionsOpen() {
  return PanelNav.isOpen('name-corrections');
}

function openNameCorrections(videoId) {
  _ncVideoId = videoId;
  PanelNav.open({
    id: 'name-corrections',
    title: 'Fix names',
    render: container => _ncMount(container),
    isDirty: () => false,
    onClose: () => { _ncVideoId = null; },
  });
}

function _ncMount(container) {
  container.innerHTML = `
    <p class="nc-intro">Reviewing the transcript for mis-heard names. Nothing changes
      until you press Apply - uncheck anything that isn't really a name.</p>
    <div id="nc-results"><div class="transcript-empty">Scanning transcript&hellip;</div></div>
    <div id="nc-footer" class="nc-footer" hidden>
      <button class="btn primary" id="nc-apply">Apply</button>
    </div>`;
  container.querySelector('#nc-apply').onclick = () => _ncApply();
  container.addEventListener('change', _ncOnChange);
  _ncScan();
}

async function _ncScan() {
  const results = document.getElementById('nc-results');
  try {
    const resp = await fetch(`/api/videos/${_ncVideoId}/name-corrections/scan`, {method: 'POST'});
    if (!resp.ok) throw new Error(formatApiError(await resp.json().catch(() => ({}))));
    const data = await resp.json();
    _ncRender(data);
  } catch (err) {
    results.innerHTML = `<div class="transcript-empty">Could not scan: ${escHtml(err.message)}</div>`;
  }
}

function _ncRender(data) {
  _ncData = data;
  const results = document.getElementById('nc-results');
  const footer = document.getElementById('nc-footer');
  if (!data.groups.length) {
    const noNames = !data.lexicon.length;
    results.innerHTML = `<div class="transcript-empty">${noNames
      ? 'No known names yet - name your speakers or add characters to a world context, then scan again.'
      : 'No likely name corrections found. Your transcript looks clean.'}</div>`;
    footer.hidden = true;
    return;
  }
  results.innerHTML = data.groups.map(_ncGroupHtml).join('');
  footer.hidden = false;
  _ncUpdateApply();
}

function _ncGroupHtml(group, gi) {
  const instances = group.instances.map((inst, ii) => _ncInstanceHtml(inst, gi, ii)).join('');
  return `
    <details class="nc-group" open>
      <summary class="nc-group-head">
        <label class="nc-check" title="Select every instance in this group">
          <input type="checkbox" class="nc-group-all" data-group="${gi}" checked>
        </label>
        <span class="nc-pattern">
          <span class="nc-from">${escHtml(group.token)}</span>
          <span class="nc-arrow" aria-hidden="true">→</span>
          <span class="nc-to">${escHtml(group.suggested)}</span>
        </span>
        <span class="nc-count">${plural(group.count, 'instance')}</span>
      </summary>
      <div class="nc-instances">${instances}</div>
    </details>`;
}

function _ncInstanceHtml(inst, gi, ii) {
  const before = inst.before ? `<span class="nc-ctx">${escHtml(inst.before)}</span> ` : '';
  const after = inst.after ? ` <span class="nc-ctx">${escHtml(inst.after)}</span>` : '';
  const line = escHtml(inst.line.slice(0, inst.token_start))
    + `<mark class="nc-mark">${escHtml(inst.line.slice(inst.token_start, inst.token_end))}</mark>`
    + escHtml(inst.line.slice(inst.token_end));
  const chips = [];
  if (!inst.speaker_scoped) chips.push('<span class="nc-chip">speaker unknown</span>');
  else if (inst.speaker) chips.push(`<span class="nc-chip">${escHtml(inst.speaker)}</span>`);
  return `
    <label class="nc-instance">
      <input type="checkbox" class="nc-inst" data-group="${gi}" data-inst="${ii}" checked>
      <span class="nc-line">${before}${line}${after}</span>
      <span class="nc-chips">${chips.join('')}</span>
    </label>`;
}

function _ncOnChange(e) {
  const groupAll = e.target.closest('.nc-group-all');
  if (groupAll) {
    const details = groupAll.closest('.nc-group');
    details.querySelectorAll('.nc-inst').forEach(cb => { cb.checked = groupAll.checked; });
  }
  const inst = e.target.closest('.nc-inst');
  if (inst) _ncSyncGroupCheckbox(inst.closest('.nc-group'));
  _ncUpdateApply();
}

function _ncSyncGroupCheckbox(details) {
  const all = details.querySelector('.nc-group-all');
  const boxes = [...details.querySelectorAll('.nc-inst')];
  all.checked = boxes.every(cb => cb.checked);
  all.indeterminate = !all.checked && boxes.some(cb => cb.checked);
}

function _ncSelected() {
  return [...document.querySelectorAll('.nc-inst:checked')].map(cb => {
    const inst = _ncData.groups[+cb.dataset.group].instances[+cb.dataset.inst];
    return {
      segment_id: inst.segment_id,
      token_start: inst.token_start,
      token_end: inst.token_end,
      token: inst.token,
      replacement: _ncData.groups[+cb.dataset.group].suggested,
    };
  });
}

function _ncUpdateApply() {
  const btn = document.getElementById('nc-apply');
  if (!btn) return;
  const n = document.querySelectorAll('.nc-inst:checked').length;
  btn.disabled = n === 0;
  btn.textContent = n ? `Apply ${plural(n, 'correction')}` : 'Apply';
}

async function _ncApply() {
  const btn = document.getElementById('nc-apply');
  const corrections = _ncSelected();
  if (!corrections.length) return;
  btn.disabled = true;
  try {
    const resp = await fetch(`/api/videos/${_ncVideoId}/name-corrections/apply`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({corrections}),
    });
    if (!resp.ok) throw new Error(formatApiError(await resp.json().catch(() => ({}))));
    const data = await resp.json();
    const skipped = data.results.length - data.applied;
    showToast(skipped
      ? `Applied ${plural(data.applied, 'correction')}; ${skipped} skipped (transcript changed)`
      : `Applied ${plural(data.applied, 'correction')}`, skipped ? 'warning' : 'success');
    if (window.reloadVideoTranscriptIfOpen) reloadVideoTranscriptIfOpen(_ncVideoId);
    const openClip = AppState.activeClipId;
    if (openClip != null && (data.affected_clip_ids || []).includes(openClip) && window.refreshClipDetail) {
      refreshClipDetail(openClip);
    }
    _ncScan();  // re-scan so applied patterns drop out and the count refreshes
  } catch (err) {
    btn.disabled = false;
    showToast(`Could not apply corrections: ${err.message}`, 'error');
  }
}

Object.assign(window, {openNameCorrections, isNameCorrectionsOpen});
})();

//# sourceURL=exporteditor.js
(function () {
// Feature-map - Clip export editor (Trim + Vertical framing + Caption Style over a live preview).
//   API: routes/clips/ (captions.py context-transcript, export.py) · Tests: tests/ui/test_ui_exporteditor.py
// ── clip export editor (Plan 07) ──────────────────────────────────────────────
// A PanelNav takeover launched before final export: transcript-driven trim with
// extendable ±30 s context, a drag-to-position 9:16 crop box, and a live caption
// preview. It edits the same start_offset/end_offset/crop_x the export dialog
// does (no new timing model, no new encode path) and, on Export, runs the exact
// single-clip export SSE the dialog uses.
//
// Own inline preview <video>: PanelNav's panel visually covers #player-area
// (known coverage bug), so the editor never relies on the main player - it
// embeds its own, proxy-preferred, exactly like the manual-clip picker.

let _edClipId       = null;
let _edClip         = null;   // saved baseline (start_offset/end_offset/crop_x)
let _edVideo        = null;   // parent recording (from AppState.videos)
let _edConfig       = {};     // caption-style defaults from /api/config
let _edLines        = [];     // context transcript (recording-relative ms)
let _edSeekOffsetS  = 0;      // segment_start_s - added to seek the parent player
let _edAspect       = 16 / 9; // source frame aspect (iw/ih), refined on metadata

let _edStartOffset  = 0;
let _edEndOffset    = 0;
let _edCropX        = 0.5;
let _edPreset       = '';
let _edCaptionMode  = 'burn'; // none | embed | burn
let _edTitleCard    = false;
let _edMetaSeeked   = false;

const _ED_MIN_DURATION_MS = 1_000;
const _ED_PAD_S = 30;

function isExportEditorOpen() {
  return PanelNav.isOpen('export-editor');
}

async function openExportEditor(clipId) {
  const clip = await fetch(`/api/clips/${clipId}`).then(r => r.ok ? r.json() : null).catch(() => null);
  if (!clip) { showToast('Could not load clip', 'error'); return; }
  const video = AppState.videos.find(v => v.id === clip.video_id);
  if (!video) { showToast('Open the recording first', 'warning'); return; }

  await ensureExportPresetsCache();
  _edConfig = await fetch('/api/config').then(r => r.ok ? r.json() : {}).catch(() => ({}));

  _edClipId      = clipId;
  _edClip        = clip;
  _edVideo       = video;
  _edLines       = [];
  _edSeekOffsetS = video.segment_start_s || 0;
  _edAspect      = 16 / 9;
  _edStartOffset = clip.start_offset || 0;
  _edEndOffset   = clip.end_offset || 0;
  _edCropX       = clip.crop_x == null ? 0.5 : clip.crop_x;
  _edPreset      = '';
  _edCaptionMode = 'burn';
  _edTitleCard   = false;
  _edMetaSeeked  = false;

  PanelNav.open({
    id: 'export-editor',
    title: `Edit & export: Clip #${clipId}`,
    render: container => _edMount(container),
    isDirty: _edIsDirty,
    onClose: _edTeardown,
  });
  _edLoadContextTranscript();
}

function _edIsDirty() {
  const savedCrop = _edClip.crop_x == null ? 0.5 : _edClip.crop_x;
  return _edStartOffset !== (_edClip.start_offset || 0)
      || _edEndOffset   !== (_edClip.end_offset || 0)
      || _edCropX       !== savedCrop;
}

// ── mount / teardown ──────────────────────────────────────────────────────────

function _edMount(container) {
  container.innerHTML = `
    <div style="font-size:12px;color:var(--muted)">
      Trim with the transcript, frame the vertical crop, preview captions, then export - in one place.
    </div>
    <div id="ed-preview-wrap" style="position:relative;height:42vh;aspect-ratio:16/9;max-width:100%;margin:0 auto;background:#000;border-radius:6px;overflow:hidden">
      <video id="ed-video" controls preload="metadata" aria-label="Clip preview"
             style="display:block;width:100%;height:100%;object-fit:contain;background:#000"></video>
      <div id="ed-crop-box" aria-hidden="true"
           style="display:none;position:absolute;top:0;bottom:0;border:2px solid var(--accent);box-sizing:border-box;box-shadow:0 0 0 9999px rgba(0,0,0,.5);cursor:ew-resize"></div>
      <div id="ed-caption-overlay" aria-hidden="true"
           style="display:none;position:absolute;left:6%;right:6%;bottom:6%;text-align:center;pointer-events:none;font-weight:600;line-height:1.3;text-shadow:0 1px 3px rgba(0,0,0,.9)"></div>
      <span id="ed-badge" role="status"
            style="display:none;position:absolute;top:8px;left:8px;background:rgba(0,0,0,.7);color:#e6e6e6;font-size:11px;padding:3px 8px;border-radius:4px"></span>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:14px;align-items:center">
      <button class="btn ghost" id="ed-play-btn" title="Play the trimmed clip on a loop">&#9654; Play selection</button>
      <div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)">Start
        <button class="btn ghost ed-nudge" data-edge="start" data-delta="-0.5" title="Start 0.5s earlier">&minus;0.5s</button>
        <strong id="ed-start-read" style="color:var(--text);font-family:monospace;min-width:70px;text-align:center"></strong>
        <button class="btn ghost ed-nudge" data-edge="start" data-delta="0.5" title="Start 0.5s later">+0.5s</button>
      </div>
      <div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)">End
        <button class="btn ghost ed-nudge" data-edge="end" data-delta="-0.5" title="End 0.5s earlier">&minus;0.5s</button>
        <strong id="ed-end-read" style="color:var(--text);font-family:monospace;min-width:70px;text-align:center"></strong>
        <button class="btn ghost ed-nudge" data-edge="end" data-delta="0.5" title="End 0.5s later">+0.5s</button>
      </div>
      <div style="font-size:13px;font-weight:600;color:var(--text)">Duration <span id="ed-duration" style="font-family:monospace"></span></div>
      <button class="btn ghost" id="ed-reset-trim" style="font-size:12px" title="Reset the trim to the original clip window">Reset trim</button>
    </div>
    <div style="font-size:11px;color:var(--muted)">Click a line's <strong>&#8676;</strong> to start the clip there or <strong>&#8677;</strong> to end it. Highlighted lines are inside the clip.</div>
    <div id="ed-transcript" class="transcript" style="max-height:24vh;overflow-y:auto"><div class="transcript-empty">Loading transcript…</div></div>
    <div style="display:flex;flex-wrap:wrap;gap:14px;align-items:center;border-top:1px solid var(--border);padding-top:12px">
      <label style="display:flex;align-items:center;gap:6px;font-size:13px;color:var(--muted)">Preset
        <select id="ed-preset" aria-label="Export preset" style="padding:5px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px">${_edPresetOptionsHtml('')}</select>
      </label>
      <label style="display:flex;align-items:center;gap:6px;font-size:13px;color:var(--muted)">Captions
        <select id="ed-captions" aria-label="Captions" style="padding:5px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px">
          <option value="none">None</option>
          <option value="embed">Embed track</option>
          <option value="burn" selected>Burn in</option>
        </select>
      </label>
      <span id="ed-caption-approx" style="font-size:11px;color:var(--muted)">Caption overlay is a preview approximation.</span>
      <label style="display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer">
        <input type="checkbox" id="ed-title-card"> Title card
      </label>
      <button class="btn-secondary" id="ed-autoframe-btn" style="display:none;font-size:12px;padding:4px 8px" title="Suggest a crop position from faces (MediaPipe)">Auto-frame on faces</button>
      <span id="ed-autoframe-note" style="font-size:11px;color:var(--muted)"></span>
      <div style="margin-left:auto;display:flex;gap:8px">
        <button class="btn ghost" id="ed-cancel-btn">Cancel</button>
        <button class="btn primary" id="ed-export-btn">Export</button>
      </div>
    </div>`;

  _edWire(container);
  _edSetupPreview();
  _edRenderReadouts();
  _edUpdateVerticalControls();
  _edApplyCaptionStyle();
}

function _edWire(container) {
  document.getElementById('ed-play-btn').onclick   = _edPlaySelection;
  document.getElementById('ed-reset-trim').onclick = _edResetTrim;
  document.getElementById('ed-cancel-btn').onclick = () => PanelNav.close();
  document.getElementById('ed-export-btn').onclick = _edExport;
  document.getElementById('ed-autoframe-btn').onclick = _edAutoFrame;
  document.getElementById('ed-crop-box').addEventListener('pointerdown', _edCropPointerDown);
  document.getElementById('ed-preset').onchange = e => { _edPreset = e.target.value; _edUpdateVerticalControls(); };
  document.getElementById('ed-captions').onchange = e => {
    _edCaptionMode = e.target.value;
    _edUpdateCaptionOverlay(_edCurrentRecordingMs());
    document.getElementById('ed-caption-approx').style.visibility = _edCaptionMode === 'burn' ? 'visible' : 'hidden';
  };
  document.getElementById('ed-title-card').onchange = e => { _edTitleCard = e.target.checked; };
  container.querySelectorAll('.ed-nudge').forEach(btn => {
    btn.onclick = () => _edNudge(btn.dataset.edge, parseFloat(btn.dataset.delta));
  });
  document.getElementById('ed-transcript').addEventListener('click', _edOnTranscriptClick);
}

function _edSetupPreview() {
  const videoEl = document.getElementById('ed-video');
  setupRecordingPreview(
    videoEl,
    document.getElementById('ed-badge'),
    _edVideo.id,
    { autoBuild: true, isCurrent: () => _edVideo && _edClipId != null, sourcePath: _edVideo.source_path },
  );
  videoEl.addEventListener('loadedmetadata', _edOnMetadata);
  videoEl.addEventListener('timeupdate', _edOnTimeUpdate);
}

function _edTeardown() {
  const videoEl = document.getElementById('ed-video');
  if (videoEl) {
    videoEl.removeEventListener('loadedmetadata', _edOnMetadata);
    videoEl.removeEventListener('timeupdate', _edOnTimeUpdate);
    try { videoEl.pause(); } catch (_) { /* ignore */ }
    videoEl.src = '';
  }
  _edClipId = null;
  _edClip   = null;
  _edVideo  = null;
  _edLines  = [];
}

// ── transcript context ────────────────────────────────────────────────────────

async function _edLoadContextTranscript() {
  const clipId = _edClipId;
  try {
    const data = await fetch(`/api/clips/${clipId}/context-transcript?pad_s=${_ED_PAD_S}`).then(r => r.json());
    if (_edClipId !== clipId) return;
    _edSeekOffsetS = data.seek_offset_s || 0;
    _edLines = data.lines || [];
    _edRenderTranscript();
  } catch (_) {
    const el = document.getElementById('ed-transcript');
    if (el && _edClipId === clipId) el.innerHTML = '<div class="transcript-empty">Could not load transcript.</div>';
  }
}

function _edRenderTranscript() {
  const el = document.getElementById('ed-transcript');
  if (!el) return;
  if (!_edLines.length) {
    el.innerHTML = '<div class="transcript-empty">No transcript for this recording - trim with the nudge buttons above.</div>';
    return;
  }
  const effStart = _edEffStartMs(), effEnd = _edEffEndMs();
  const rows = _edLines.map(line => {
    const inClip = line.start_ms < effEnd && line.end_ms > effStart;
    const clock  = _edClock(line.start_ms);
    const spk = line.speaker
      ? `<span class="tline-speaker" style="align-self:center;margin-top:0${line.color ? `;color:${escHtml(line.color)}` : ''}">${escHtml(line.speaker)}</span>`
      : '';
    return `<div class="tline${inClip ? ' cc-selected' : ''}" data-start-ms="${line.start_ms}" data-end-ms="${line.end_ms}"${inClip ? '' : ' style="opacity:.55"'}>
      <button class="tline-play" data-seek-ms="${line.start_ms}" title="Play from ${clock}" aria-label="Play from ${clock}">&#9654;</button>
      <span class="tline-time">${clock}</span>
      <button class="btn ghost ed-bound" data-edge="start" data-ms="${line.start_ms}" title="Start the clip at this line" aria-label="Start clip here" style="padding:0 6px;font-size:13px">&#8676;</button>
      ${spk}
      <span class="tline-text" style="flex:1">${escHtml(line.text)}</span>
      <button class="btn ghost ed-bound" data-edge="end" data-ms="${line.end_ms}" title="End the clip at this line" aria-label="End clip here" style="padding:0 6px;font-size:13px">&#8677;</button>
    </div>`;
  }).join('');
  el.innerHTML = `<div class="transcript-lines">${rows}</div>`;
}

function _edOnTranscriptClick(e) {
  const bound = e.target.closest('.ed-bound');
  if (bound) { _edSetBoundaryToLine(bound.dataset.edge, parseInt(bound.dataset.ms, 10)); return; }
  const play = e.target.closest('.tline-play');
  if (play) { _edSeekMs(parseInt(play.dataset.seekMs, 10), true); }
}

// ── trim boundaries ───────────────────────────────────────────────────────────

function _edEffStartMs() { return _edClip.start_ms + _edStartOffset * 1000; }
function _edEffEndMs()   { return _edClip.end_ms   + _edEndOffset   * 1000; }

function _edSetBoundaryToLine(edge, ms) {
  if (edge === 'start') _edApplyStartMs(ms);
  else                  _edApplyEndMs(ms);
}

function _edApplyStartMs(effStartMs) {
  effStartMs = Math.max(0, effStartMs);
  if (_edEffEndMs() - effStartMs < _ED_MIN_DURATION_MS) {
    showToast('Clip must stay at least 1 second long', 'warning');
    return;
  }
  _edStartOffset = +((effStartMs - _edClip.start_ms) / 1000).toFixed(3);
  _edAfterBoundaryChange();
}

function _edApplyEndMs(effEndMs) {
  if (effEndMs - _edEffStartMs() < _ED_MIN_DURATION_MS) {
    showToast('Clip must stay at least 1 second long', 'warning');
    return;
  }
  _edEndOffset = +((effEndMs - _edClip.end_ms) / 1000).toFixed(3);
  _edAfterBoundaryChange();
}

function _edNudge(edge, deltaS) {
  if (edge === 'start') _edApplyStartMs(_edEffStartMs() + deltaS * 1000);
  else                  _edApplyEndMs(_edEffEndMs() + deltaS * 1000);
}

function _edResetTrim() {
  _edStartOffset = 0;
  _edEndOffset   = 0;
  _edAfterBoundaryChange();
}

function _edAfterBoundaryChange() {
  _edRenderReadouts();
  _edRenderTranscript();
  _edSeekMs(_edEffStartMs(), false);
}

function _edRenderReadouts() {
  const startEl = document.getElementById('ed-start-read');
  const endEl   = document.getElementById('ed-end-read');
  const durEl   = document.getElementById('ed-duration');
  if (startEl) startEl.textContent = _edClock(_edEffStartMs());
  if (endEl)   endEl.textContent   = _edClock(_edEffEndMs());
  if (durEl)   durEl.textContent   = `${((_edEffEndMs() - _edEffStartMs()) / 1000).toFixed(1)}s`;
}

// ── preview playback ──────────────────────────────────────────────────────────

function _edOnMetadata() {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl || !videoEl.videoWidth) return;
  _edAspect = videoEl.videoWidth / videoEl.videoHeight;
  const wrap = document.getElementById('ed-preview-wrap');
  if (wrap) wrap.style.aspectRatio = `${videoEl.videoWidth}/${videoEl.videoHeight}`;
  _edUpdateVerticalControls();
  _edApplyCaptionStyle();
  if (!_edMetaSeeked) {
    _edMetaSeeked = true;
    _edSeekMs(_edEffStartMs(), false);
  }
}

function _edOnTimeUpdate() {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl) return;
  _edUpdateCaptionOverlay(_edCurrentRecordingMs());
  if (!videoEl.paused) {
    const endParent = _edSeekOffsetS + _edEffEndMs() / 1000;
    if (videoEl.currentTime >= endParent - 0.03) {
      videoEl.currentTime = _edSeekOffsetS + _edEffStartMs() / 1000;
    }
  }
}

function _edCurrentRecordingMs() {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl) return 0;
  return (videoEl.currentTime - _edSeekOffsetS) * 1000;
}

// recordingMs is recording-relative; add the segment offset to seek the parent.
function _edSeekMs(recordingMs, play) {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl) return;
  videoEl.currentTime = Math.max(0, _edSeekOffsetS + recordingMs / 1000);
  if (play) { const p = videoEl.play(); if (p && p.catch) p.catch(() => {}); }
}

function _edPlaySelection() {
  _edSeekMs(_edEffStartMs(), true);
}

// ── caption overlay (preview approximation) ───────────────────────────────────

function _edApplyCaptionStyle() {
  const overlay = document.getElementById('ed-caption-overlay');
  const wrap    = document.getElementById('ed-preview-wrap');
  const videoEl = document.getElementById('ed-video');
  if (!overlay || !wrap) return;
  const sourceH = (videoEl && videoEl.videoHeight) || 1080;
  const sizePt  = _edConfig.caption_font_size || 28;
  const px      = Math.max(11, sizePt * (wrap.clientHeight || 1) / sourceH);
  overlay.style.fontSize   = `${px.toFixed(1)}px`;
  overlay.style.fontFamily = _edConfig.caption_font_name ? `"${_edConfig.caption_font_name}", sans-serif` : '';
  const top = (_edConfig.caption_position === 'top');
  overlay.style.bottom = top ? '' : '6%';
  overlay.style.top    = top ? '6%' : '';
}

function _edUpdateCaptionOverlay(recordingMs) {
  const overlay = document.getElementById('ed-caption-overlay');
  if (!overlay) return;
  if (_edCaptionMode !== 'burn') { overlay.style.display = 'none'; return; }
  const active = _edLines.filter(l => l.in_clip && l.start_ms <= recordingMs && l.end_ms > recordingMs);
  if (!active.length) { overlay.style.display = 'none'; return; }
  overlay.style.display = 'block';
  overlay.innerHTML = active
    .map(l => `<span style="color:${escHtml(l.color || '#fff')}">${escHtml(l.text)}</span>`)
    .join('<br>');
}

// ── vertical crop box ─────────────────────────────────────────────────────────

// Fraction of frame width the 9:16 crop column occupies: min(1, (9/16)/aspect).
function _edCropWFrac() {
  return Math.min(1, (9 / 16) / _edAspect);
}

function _edUpdateVerticalControls() {
  const vertical = exportPresetIsVertical(_edPreset);
  const box = document.getElementById('ed-crop-box');
  const btn = document.getElementById('ed-autoframe-btn');
  if (btn) btn.style.display = vertical ? '' : 'none';
  if (!box) return;
  if (!vertical) { box.style.display = 'none'; return; }
  box.style.display = 'block';
  _edRenderCropBox();
}

function _edRenderCropBox() {
  const box = document.getElementById('ed-crop-box');
  if (!box) return;
  const wFrac = _edCropWFrac();
  box.style.width = `${(wFrac * 100).toFixed(2)}%`;
  box.style.left  = `${(_edCropX * (1 - wFrac) * 100).toFixed(2)}%`;
}

function _edSetCropX(fraction) {
  _edCropX = Math.max(0, Math.min(1, fraction));
  _edRenderCropBox();
}

function _edCropPointerDown(e) {
  e.preventDefault();
  const wrap  = document.getElementById('ed-preview-wrap');
  const wFrac = _edCropWFrac();
  if (wFrac >= 0.999 || !wrap) return;  // source already ≤9:16 - nothing to pan
  function onMove(ev) {
    const rect = wrap.getBoundingClientRect();
    const centerFrac = (ev.clientX - rect.left) / rect.width;
    _edSetCropX((centerFrac - wFrac / 2) / (1 - wFrac));
  }
  function onUp() {
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup', onUp);
  }
  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup', onUp);
}

async function _edAutoFrame() {
  const btn  = document.getElementById('ed-autoframe-btn');
  const note = document.getElementById('ed-autoframe-note');
  btn.disabled = true;
  note.textContent = 'Finding faces…';
  try {
    const res = await fetch(`/api/clips/${_edClipId}/suggest-framing`, { method: 'POST' });
    if (res.status === 503) { note.textContent = 'Needs MediaPipe - install it in Settings → Export.'; return; }
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))) || `HTTP ${res.status}`);
    const { crop_x } = await res.json();
    if (crop_x == null) { note.textContent = 'No face found - set the crop manually.'; return; }
    _edSetCropX(crop_x);
    note.textContent = 'Framed on faces.';
  } catch (err) {
    note.textContent = `Auto-frame failed: ${err.message}`;
  } finally {
    btn.disabled = false;
  }
}

// ── export ────────────────────────────────────────────────────────────────────

function _edPresetOptionsHtml(selected) {
  const presets = AppState.exportPresets || { builtins: [], custom: [] };
  const opt = (v, l) => `<option value="${escHtml(v)}"${selected === v ? ' selected' : ''}>${escHtml(l)}</option>`;
  return [
    opt('', 'Original quality'),
    ...(presets.builtins || []).map(p => opt(p.name, p.label)),
    ...(presets.custom || []).map(p => opt(p.name, p.label)),
  ].join('');
}

async function _edSaveEdits() {
  const timingRes = await fetch(`/api/clips/${_edClipId}/timing`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ start_offset: _edStartOffset, end_offset: _edEndOffset }),
  }).catch(() => null);
  if (!timingRes || !timingRes.ok) { showToast('Failed to save trim', 'error'); return false; }

  if (exportPresetIsVertical(_edPreset)) {
    const framingRes = await fetch(`/api/clips/${_edClipId}/framing`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ crop_x: _edCropX }),
    }).catch(() => null);
    if (!framingRes || !framingRes.ok) { showToast('Failed to save vertical framing', 'error'); return false; }
    _edClip.crop_x = _edCropX;
  }
  _edClip.start_offset = _edStartOffset;
  _edClip.end_offset   = _edEndOffset;
  return true;
}

function _edExportParams() {
  const params = new URLSearchParams();
  if (_edCaptionMode === 'burn')  params.set('burn_subs', 'true');
  if (_edCaptionMode === 'embed') params.set('embed_subs', 'true');
  if (_edPreset)   params.set('preset', _edPreset);
  if (_edTitleCard) params.set('title_card', 'true');
  if (_edCaptionMode === 'burn') {
    params.set('caption_font', _edConfig.caption_font_name || '');
    params.set('caption_size', String(_edConfig.caption_font_size || 0));
    params.set('caption_position', _edConfig.caption_position || 'bottom');
  }
  return params;
}

async function _edExport() {
  const id  = _edClipId;
  const btn = document.getElementById('ed-export-btn');
  btn.disabled = true;
  if (!await _edSaveEdits()) { btn.disabled = false; return; }

  const params = _edExportParams();
  const qs = params.toString() ? `?${params}` : '';
  openLog();
  streamSSE(
    `/api/clips/${id}/export${qs}`,
    async () => {
      const [clip, media] = await Promise.all([
        fetch(`/api/clips/${id}`).then(r => r.json()),
        fetch(`/api/clips/${id}/media_url`).then(r => r.json()),
      ]);
      AppState.activeClipData = clip;
      AppState.activeMediaFilename = media.filename;
      PanelNav.forceClose();
      const captionsUrl = media.has_captions ? `/api/clips/${id}/captions.vtt` : null;
      renderPlayer(media.url, captionsUrl, id);
      renderDetail(clip);
      await _reloadClipList(AppState.activeVideoId);
      loadVideos();
      showToast('Clip exported successfully');
      SoundFx.play('export');
    },
    [{ label: 'Export', patterns: ['Exporting', 'OK Saved'] }],
    'Exporting',
  );
}

// ── helpers ───────────────────────────────────────────────────────────────────

function _edClock(ms) {
  const total = Math.max(0, Math.round((ms || 0) / 1000));
  const s = total % 60, m = Math.floor(total / 60) % 60, h = Math.floor(total / 3600);
  const mm = String(m).padStart(2, '0'), ss = String(s).padStart(2, '0');
  return h ? `${h}:${mm}:${ss}` : `${m}:${ss}`;
}

Object.assign(window, {
  openExportEditor, isExportEditorOpen,
});
})();

//# sourceURL=boot.js
// Infrastructure - first-paint boot wiring (a11y init, event hookup, initial load).
//   Not a feature module; loaded last in index.html. Entry point: exports nothing,
//   so it is a bare IIFE with no Object.assign(window, ...) list.
// ── accessibility init ────────────────────────────────────────────────────────
(function () {
document.querySelectorAll('.modal-bg').forEach((bg, i) => {
  const inner = bg.querySelector('.modal, [class*="modal"]');
  if (!inner) return;
  inner.setAttribute('role', 'dialog');
  inner.setAttribute('aria-modal', 'true');
  const heading = inner.querySelector('h3');
  if (heading) {
    const labelId = `modal-title-${i}`;
    heading.id = heading.id || labelId;
    inner.setAttribute('aria-labelledby', heading.id || labelId);
  }
});

// ── boot ──────────────────────────────────────────────────────────────────────
initResize();
initPlaybackRate();
initProjectSwitcher();
_loadContexts();
loadVideos();
ensureHotwordsCache();
ensureExportPresetsCache();
fetch('/api/status').then(r => r.json()).then(d => {
  if (d.version) {
    const versionLabel = (/^\d/.test(d.version) ? 'v' : '') + d.version;
    document.getElementById('version-tag').textContent = versionLabel;
    document.getElementById('about-version').textContent = `Version ${versionLabel}`;
  }
  AppState.exportDir = d.export_dir || null;
  AppState.reelsDir = d.reels_dir || null;
  AppState.canReveal = !!d.can_reveal;
  // Reconnect to an analysis that was already running when this page loaded
  // (e.g. after a refresh) - the subprocess survives independently of the stream.
  if (d.analyze_filename) reattachAnalysis(d.analyze_filename, d.analyze_paused);
}).catch(() => {});

if (window.electronAPI) {
  document.getElementById('btn-setup-wizard').style.display = '';
  document.getElementById('btn-refresh').style.display = '';
}

// Single place that (re)loads the boot-cached server state and re-renders every
// surface that reads it, so a server-side change (model download, settings save)
// shows up WITHOUT an app restart. Cached globals and their readers:
//   window._prereqs      -> analyze prereq banner (ui.js), "Basic description"
//                           chip (clips.js), ffmpeg gate (videos.js)
//   window._aiPrivacyMode -> "Basic description" chip (clips.js)
//   window._visionEnabled -> vision frames (clips.js, contexts.js)
// Call refreshServerState() from any action that mutates these on the server.
window._prereqs = {ffmpeg_ok: true, llm_ok: true, llm_reason: ''};
async function refreshServerState() {
  try {
    const cfg = await fetch('/api/config').then(r => r.json());
    window._aiPrivacyMode = cfg.ai_privacy_mode || 'local_only';
    window._visionEnabled = cfg.vision_enabled === true;
  } catch { /* keep the last known config on a transient fetch failure */ }
  try {
    const prereqs = await fetch('/api/prereqs').then(r => r.json());
    window._prereqs = prereqs;
    if (window._applyPrereqWarnings) _applyPrereqWarnings(prereqs);
  } catch { /* keep the last known prereqs */ }
  if (window._renderClips) _renderClips();  // basic-description chip + vision frames
}
window.refreshServerState = refreshServerState;
refreshServerState();
const _savedSort = localStorage.getItem('clips-sort');
if (_savedSort) document.getElementById('clips-sort').value = _savedSort;
const _savedVideoSort = localStorage.getItem('videos-sort');
if (_savedVideoSort) {
  AppState.videoSort = _savedVideoSort;
  document.getElementById('videos-sort').value = _savedVideoSort;
}
AppState.clipSortDir = localStorage.getItem('clips-sort-dir') || 'desc';
AppState.videoSortDir = localStorage.getItem('videos-sort-dir') || 'desc';
_syncSortDirBtn('clips-sort-dir', AppState.clipSortDir);
_syncSortDirBtn('videos-sort-dir', AppState.videoSortDir);
document.getElementById('log-panel').classList.add('visible', 'minimized');
document.getElementById('log-toggle').textContent = '▼';

if (!localStorage.getItem('yuu-getting-started-seen')) openGettingStartedModal();

// Background model-download handoffs (first-run-friction Stages 4 + 6): if the
// wizard queued a local model and none is ready yet, and/or the always-needed
// analysis models (speech + speaker) are not cached and prefetch is enabled, fetch
// them in the background with in-app progress banners that stack. Non-blocking -
// the app stays fully usable.
initModelDownload();
initModelPrefetch();
})();
